(window.FREALLY_I18N = window.FREALLY_I18N || {})["ar"] = {"hero.headline":"<span class=\"hl-muted\">شاهد أيديًا حقيقية تعزف موسيقاك.</span> <span class=\"cycle\" data-cycle=\"hero.cycle\" data-words=\"Then drag it into your DAW.|Read every note.|Learn how it is played.\">ثم اسحبها إلى الـ DAW الخاص بك.</span>","hero.cycle":"ثم اسحبها إلى الـ DAW الخاص بك.|اقرأ كل نغمة.|تعلّم كيف تُعزف.","hero.sub":"أكوردات ولحن وخط باص ولحن مضاد، مكتوبة بأي أسلوب، تُعرض كنوتات موسيقية وتعزفها أيدٍ واقعية على آلات واقعية، من البيانو والغيتار حتى فرقة كاملة. ومعها دروس موسيقى تعلّمك أن تعزفها وتكتبها وتوزّعها بنفسك. بلا اتصال وخالٍ من الذكاء الاصطناعي بنسبة 100%.","hero.chipStandalone":"مستقل","what.title":"ما هو","what.p1":"معظم من يستخدمون مولّد أكوردات لا يرون أبدًا كيف ستُعزف أجزاؤه، ومعظم من يتعلّمون آلة موسيقية لا يرون أبدًا يدي العازف عن قرب. Handscore يريك الأمرين معًا.","what.p2":"اختر نوعًا موسيقيًا أو فنانًا أو منتجًا، فيكتب Handscore أربعة أجزاء بذلك الأسلوب: أكوردات ولحنًا وخط باص ولحنًا مضادًا. تظهر كنوتات موسيقية على حامل النوتة الخاص بالآلة، وتعزفها أيدٍ واقعية كما يعزفها عازف تلك الآلة: كل إصبع على المفتاح الذي كان عازف البيانو سيستخدمه، وكل دستان وكل ضربة على الأوتار كما كان عازف الغيتار سيفعل. تأتي البيانوهات أولًا، ثم الغيتارات وغيتار الباص، وبعدها كل عائلة من الآلات، حتى فرقة كاملة.","what.p3":"تظهر كل نغمة حيث تُعزف، ويحمل كل مفتاح بيانو اسمه على واجهته، فترى بالضبط ما الذي يُسمَع. وحين يصبح جزء ما كما تريد، اسحبه من نوتته مباشرةً إلى مسار في الـ DAW الخاص بك.","what.p4":"وهو يعلّم أيضًا. تبدأ الدروس من اليوم الأول على البيانو، فتستمع إليك وأنت تعزف وتمضي قُدمًا حين تُتقن ما تعزفه، ثم تنتقل إلى قراءة النوتة الموسيقية، والإيقاع، وتدريب الأذن، ونظرية الموسيقى، وكتابة الأغاني وكلماتها، وتوزيع الأغاني، والمزج، والعزف على الطبول بالأصابع، وطقم الطبول.","inside.title":"ما سيفعله","inside.instruments.title":"كل عائلات الآلات","inside.instruments.body":"أربعة بيانوهات حقيقية أولًا، ثم وحدة تحكم بالوسادات وطقم طبول، والغيتارات وغيتار الباص؛ وبعدها الأورغنات، وآلات المطارق، والهارب، والوتريات التي تُعزف بالقوس، وآلات النفخ الخشبية، وآلات النفخ النحاسية، حتى فرقة كاملة، عائلةً تلو الأخرى.","inside.hands.title":"أيدٍ واقعية","inside.hands.body":"يدان تعزفان كل نغمة كما يفعل عازف تلك الآلة: بالإصبع الذي كان عازف البيانو سيختاره، وبالدستان والضربة اللذين كان عازف الغيتار سيستخدمهما.","inside.lessons.title":"دروس الموسيقى","inside.lessons.body":"دورات تمتد من نغماتك الأولى على البيانو إلى قراءة النوتة الموسيقية، والإيقاع، وتدريب الأذن، ونظرية الموسيقى، وكتابة الأغاني وكلماتها، وتوزيع الأغاني، والمزج. تستمع إليك وأنت تعزف، وتقرأ لك كل درس حين تفعّل «القراءة بصوت عالٍ».","inside.drums.title":"الطبول","inside.drums.body":"آلة طبول بعيّناتك الخاصة على وساداتها ومُتسلسِل خطوات، ووحدة تحكم ذات وسادات تضيء مع كل ضربة، وطقم طبول تعزفه يدا عازف طبول وقدماه، مع دورات في العزف على الطبول بالأصابع وطقم الطبول.","inside.sheets.title":"أربع نوتات موسيقية","inside.sheets.body":"الأكوردات واللحن واللحن المضاد والباص، كلٌّ على نوتته الخاصة، وتضيء كل نغمة لحظة عزفها.","inside.styles.title":"كل أسلوب يعرفه Freally MIDI Master","inside.styles.body":"73 نوعًا موسيقيًا و1507 فنانين و833 منتجًا، من المولّدات نفسها القائمة على القواعد.","inside.drag.title":"اسحب ملف MIDI","inside.drag.body":"جزء واحد في كل مرة أو الأجزاء الأربعة معًا، تُسحب من النوتات مباشرةً إلى الـ DAW الخاص بك، أو تُحفظ كملف MIDI أو كملف PDF للنوتات.","inside.views.title":"عرض أمامي وعلوي وجانبي","inside.views.body":"بدّل بينها بينما تُعزف الموسيقى؛ تدور النوتات لتبقى مقروءة ولا تفوّت الأيدي أي نغمة.","inside.daw.title":"في أي DAW","inside.daw.body":"CLAP وVST3 وAU، إضافةً إلى تطبيق مستقل. Windows وmacOS وLinux.","inside.offline.title":"بلا اتصال، بلا ذكاء اصطناعي","inside.offline.body":"لا حساب، لا قياس عن بُعد، لا شبكة، لا نموذج. كل جزء وكل توزيع للأصابع وكل حركة يأتي من قواعد، تفرضها بوابة بناء لا مجرد وعد بها.","ladder.title":"الطريق إلى 1.0، ثم إلى 2.0","ladder.intro":"سطر واحد لكل إصدار. تأتي الدروس والعزف على الطبول بالأصابع وآلة الإيقاع وطقم الطبول والغيتارات وغيتار الباص قبل 1.0. وبعده، يجلب كل إصدار عائلة جديدة من الآلات، تعزفها أيدٍ واقعية بالطريقة التي سيريك بها معلّم.","ladder.rung.v0.1.0":"الأساس: يُحمَّل المكوّن الإضافي بصيغ CLAP وVST3 وAU وكتطبيق مستقل، ويطلب منك قبول ترخيصه، ويُفتح على لوحة مفاتيح من 88 مفتاحًا لكلٍّ منها اسمه.","ladder.rung.v0.2.0":"البيانوهات الحقيقية: الكبير والأكوستيك والقائم والهونكي تونك، تتحرك مفاتيحها وتصدر أصواتها أثناء العزف.","ladder.rung.v0.3.0":"أيدٍ واقعية على لوحة المفاتيح، تعزف كل نغمة بالأصابع التي كان عازف البيانو سيختارها، مع اثنتين وستين قطعة كلاسيكية من الملكية العامة للتعلّم وشريط تشغيل للتنقّل فيها وأنت تسمعها.","ladder.rung.v0.4.0":"ولّد بأي أسلوب، واقرأ النوتات الأربع وهي تضيء، واسحب ملف MIDI إلى الـ DAW الخاص بك.","ladder.rung.v0.5.0":"العرضان العلوي والجانبي، مع النوتات ممدّدة على البيانو، وانتقال سلس بين العروض.","ladder.rung.lessons-1":"دروس من اليوم الأول: دورة بيانو تستمع إليك وأنت تعزف وتمضي قُدمًا حين تُتقن ما تعزفه، ومفتاح «القراءة بصوت عالٍ» الذي يقرأ لك كل درس، وتضيء كل كلمة لحظة نطقها.","ladder.rung.mixer":"ميكسر لكل جزء، مع الفيدرات والبان والـ EQ والمؤثرات والضغط الديناميكي، ويبقى المزج محفوظًا عند السحب.","ladder.rung.song-view":"عرض الأغنية: ابنِ أغنية كاملة يدويًا من مقاطعها، أو ابدأ من توزيع فنان أو نوع موسيقي، ثم شاهدها تُعزف واسحبها إلى الـ DAW الخاص بك.","ladder.rung.lessons-2":"مزيد من الدورات: قراءة النوتة الموسيقية، والإيقاع، وتدريب الأذن، ونظرية الموسيقى بنظام Nashville Number System، وكتابة الأغاني وكلماتها، والتوزيع، والمزج.","ladder.rung.finger-drumming":"العزف على الطبول بالأصابع على وحدة تحكم ذات وسادات تضيء مع كل ضربة، من أول إيقاع حتى الإيقاعات الكاملة.","ladder.rung.drum-kit":"طقم طبول مُجهَّز ومعزوف بالطريقة التي يتبعها عازف طبول محترف، وبجانبه آلة إيقاع، مع مفتاح واحد تختار به أيّهما يعزف طبولك.","ladder.rung.live-listening":"الاستماع المباشر: اعزف على آلة حقيقية أو غنِّ عبر ميكروفون أو كابل آلة موسيقية، فتسمعك الدروس، مع موالف ومعايرة لزمن التأخّر.","ladder.rung.guitars":"الغيتارات: الأكوستيك والنايلون والكهربائي والمكتوم، مع ضغط حقيقي على الدساتين ونقر وضرب على الأوتار.","ladder.rung.bass":"غيتار الباص، يُعزف بالأصابع وبأسلوب السلاب.","ladder.rung.own-audio":"ملفات الصوت وMIDI الخاصة بك، تُقرأ إلى أجزاء وتعزفها الأيدي.","ladder.rung.classics":"الكلاسيكيات: ألحان من الملكية العامة للمشاهدة والاستماع.","ladder.rung.realism":"مرحلة الواقعية: الإضاءة والخامات والحركة مُقاسة على عزف مصوَّر.","ladder.rung.finish":"اللمسات الأخيرة: الإعدادات، وثماني عشرة لغة في كل مكان، وإمكانية الوصول، والدليل.","ladder.rung.v1.0.0-beta.1":"إشعارات التحديث والإصداران التجريبي والمدفوع.","ladder.rung.v1.0.0":"الإصدار العام الأول.","ladder.rung.v1.1.0":"البيانوهات الكهربائية والأورغنات، والأورغنات بلوحة دواسات لخط الباص.","ladder.rung.v1.2.0":"الهاربسيكورد والكلافينيت والسيليستا وبيانو الألعاب؛ والأوكوليلي والبانجو والماندولين.","ladder.rung.v1.3.0":"آلات المطارق: الزيلوفون والماريمبا والفيبرافون والغلوكنشبيل.","ladder.rung.v1.4.0":"الهارب والكوتو والسيتار والدولسيمر الجبلي.","ladder.rung.v1.5.0":"الكمان والفيولا والتشيلو والكونترباص، بالقوس وبالنقر.","ladder.rung.v1.6.0":"الفلوت والكلارينيت والساكسفونات والأوبوا والريكوردر.","ladder.rung.v1.7.0":"الترومبيت والترومبون والهورن الفرنسي والتوبا.","ladder.rung.play-along":"وضع العزف المصاحب والتعلّم.","ladder.rung.v2.0.0":"الفرقة: كل جزء على آلته الخاصة، ولكل آلة عازفها.","ladder.note":"الإصدار المكتمل مبنيّ ومُوسوم. إنه ليس تنزيلًا: لا توجد أي تنزيلات قبل 1.0.0.","honest.title":"أين هو اليوم","honest.start.title":"لا يزال في بدايته الأولى","honest.start.body":"يُحمَّل الإصدار 0.12.0 في DAW ويفتح على أربعة بيانوهات حقيقية تعزفها يدان واقعيتان، تراها من الأمام أو من الأعلى أو من الجانب، والكاميرا تنساب بين العروض والموسيقى تعزف. ابحث عن نوع موسيقي أو فنان أو منتج، واضغط توليد، فتُكتب أربعة أجزاء بذلك الأسلوب، وتُطبع نوتةً على حامل نوتة البيانو وتعزفها اليدان — جاهزة للسحب إلى DAW لديك بصيغة MIDI أو كصوت، أو التعديل نغمةً نغمة، أو التصدير بصيغة MIDI أو PDF. يعزف كل جزء عبر مساره الخاص في مازج، مع محرّر أغلفة لتشكيله، ويمكن أن يعزف بإحدى آلاتك الخاصة. ويبني عرض الأغنية أغانيَ كاملة قسمًا قسمًا، مع درجة جاهزية النجاح وأدوات كاتب الأغاني. هناك اثنتان وستون قطعة كلاسيكية من الملك العام لتتعلّمها، مع شريط نقل للإيقاف المؤقت والرجوع والتنقّل في الأغنية، ويعلّم وضع الدروس اثنتي عشرة دورة — البيانو حتى الدرجة الخامسة تقريبًا، وقراءة النوتة، والإيقاع، وتدريب الأذن، والنظرية، وكتابة الأغاني، والكلمات، والراب، والتوزيع، والمزج، والعزف على الطبول بالأصابع، وطقم الطبول — ويستمع إليك وأنت تعزف، عبر MIDI أو، مع تشغيل «الاستماع»، إلى آلة حقيقية أو إلى صوتك عبر ميكروفون أو كابل. وتُعزف الطبول على آلة طبول بعيّناتك الخاصة على وساداتها ومُتسلسِل خطوات، أو على طقم طبول، ومفتاح واحد بينهما. ويمكن أن تعتلي المسرحَ وحدةُ تحكم بالوسادات أو الطقمُ بدلًا من ذلك، فتعزف اليدان وعازف الطبول طبول الحلقة، ويمكنك أن تعزف طبولك الخاصة وتسجّلها، طبقةً فوق طبقة. وتأتي كل آلة أخرى ودورات جديدة إصدارًا بعد إصدار، كما يبيّن السلّم أعلاه.","honest.downloads.title":"لا توجد تنزيلات قبل 1.0.0","honest.downloads.body":"لا نسخة تجريبية على هذه الصفحة، ولا بناء مسبق، ولا وصول مبكر.","honest.network.title":"Handscore نفسه لا يتصل بالإنترنت أبدًا","honest.network.body":"لا يحتوي المكوّن الإضافي ولا التطبيق المستقل على أي شيفرة شبكة، وتفشل بوابة بناء إذا أُضيفت أي شيفرة من هذا القبيل. أما الآلة الخاصة التي تحمّلها في جزء فهي شأنك: تعمل في عملية خاصة بها وتفعل ما تفعله دائمًا. قد يضيف إصدار لاحق فحص تحديثات يبقى مطفأً ما لم تُفعّله بنفسك، ويشغّله برنامج منفصل.","site.tagline":"شاهد أيديًا حقيقية تعزف موسيقاك. ثم اسحبها إلى الـ DAW الخاص بك.","footer.licence":"ملكية خاصة — جميع الحقوق محفوظة. © 2026 Mike Weaver، الذي يمارس نشاطه التجاري باسم Havoc Software. ليس مفتوح المصدر.","footer.yours":"ملفات MIDI التي تولّدها وتسحبها إلى الـ DAW الخاص بك ملك لك. لا يدّعي مؤلف Handscore أي ملكية لها.","featuresPage.lead":"أربعة أجزاء مكتوبة بأي أسلوب، تُعرض كنوتات موسيقية وتعزفها أيدٍ واقعية على آلات واقعية، وكل جزء يُسحب مباشرةً إلى الـ DAW الخاص بك، ودروس موسيقى تعلّمك أن تعزفها وتكتبها وتوزّعها بنفسك.","featuresPage.version":"تصف هذه الصفحة ما سيفعله Freally Handscore في الإصدار 1.0. الإصدار الحالي هو 0.12.0: انظر الطريق إلى 1.0 في الصفحة الرئيسية.","featuresPage.numbers.parts":"أجزاء: الأكوردات واللحن واللحن المضاد والباص","featuresPage.numbers.genres":"نوعًا موسيقيًا","featuresPage.numbers.artists":"فنانين","featuresPage.numbers.producers":"منتجًا","featuresPage.numbers.keys":"مفتاحًا، لكلٍّ منها اسمه على واجهته","featuresPage.numbers.plugins":"صيغ مكوّنات إضافية، إضافةً إلى تطبيق مستقل","featuresPage.numbers.languages":"لغة","featuresPage.numbers.ai":"نماذج ذكاء اصطناعي","featuresPage.free.title":"مجاني اليوم","featuresPage.free.body":"Handscore مجاني اليوم: لا فئة مدفوعة، ولا اشتراك، ولا حساب. لا يوجد شيء لتنزيله بعد، لأنه لا توجد تنزيلات قبل الإصدار 1.0.0، وقد تُباع الإصدارات اللاحقة.","featuresPage.cards.title":"ما يفعله الإصدار 1.0","featuresPage.cards.pianos.title":"أربعة بيانوهات حقيقية","featuresPage.cards.pianos.body":"بيانو كبير وبيانو أكوستيك وبيانو قائم وبيانو هونكي تونك، كلٌّ منها تتحرك مفاتيحه مع صدور أصواتها، ويُعزف بأصوات البيانو المقيسة نفسها التي يستخدمها Freally MIDI Master.","featuresPage.cards.strings.title":"الغيتارات وغيتار الباص","featuresPage.cards.strings.body":"غيتارات أكوستيك ونايلون وكهربائية ومكتومة، بضغط حقيقي على الدساتين ونقر وضرب على الأوتار، وغيتار الباص، يُعزف بالأصابع وبأسلوب السلاب.","featuresPage.cards.hands.title":"أيدٍ واقعية","featuresPage.cards.hands.body":"يدان تعزفان كل نغمة كما يفعل العازف: بالإصبع الذي كان عازف البيانو سيختاره، وبالدستان والضربة اللذين كان عازف الغيتار سيستخدمهما.","featuresPage.cards.sheets.title":"أربع نوتات موسيقية","featuresPage.cards.sheets.body":"الأكوردات واللحن واللحن المضاد والباص، كلٌّ على نوتته الخاصة، وتضيء كل نغمة لحظة عزفها.","featuresPage.cards.styles.title":"كل أسلوب يعرفه Freally MIDI Master","featuresPage.cards.styles.body":"اختر من بين 73 نوعًا موسيقيًا أو 1507 فنانين أو 833 منتجًا، فتكتب المولّدات نفسها القائمة على القواعد الأجزاء الأربعة بذلك الأسلوب.","featuresPage.cards.yours.title":"ملفات الصوت وMIDI الخاصة بك","featuresPage.cards.yours.body":"أحضر ملفات الصوت أو MIDI الخاصة بك، فيقرؤها Handscore إلى أجزاء تعزفها الأيدي.","featuresPage.cards.classics.title":"الكلاسيكيات","featuresPage.cards.classics.body":"أغانٍ من الملكية العامة للتعلّم، من أغاني الأطفال وتراتيل الميلاد إلى الأناشيد والألحان الكلاسيكية، كلٌّ منها موزّعة لليدين وتعزفها اليدان على المسرح. ولا يمكن أن يغادر Handscore منها سوى أكورداتها.","featuresPage.cards.lessons.title":"دروس الموسيقى","featuresPage.cards.lessons.body":"دورة بيانو من اليوم الأول تستمع إليك وأنت تعزف وتمضي قُدمًا حين تُتقن ما تعزفه، ثم دورات في قراءة النوتة الموسيقية، والإيقاع، وتدريب الأذن، ونظرية الموسيقى، وكتابة الأغاني وكلماتها، وتوزيع الأغاني، والمزج، والعزف على الطبول بالأصابع، وطقم الطبول. فعّل «القراءة بصوت عالٍ» فيُقرأ لك كل درس، وتضيء كل كلمة لحظة نطقها. فعّل «الاستماع» فتسمع الدروس آلة حقيقية أو صوتك عبر ميكروفون أو كابل، على هذا الحاسوب فقط.","featuresPage.cards.drums.title":"آلة الطبول وطقم الطبول","featuresPage.cards.drums.body":"آلة طبول بعيّناتك الخاصة على وساداتها، يُشكَّل صوت كل وسادة فيها وتُبرمَج خطواتها، وطقم طبول احترافي تعزفه يدا عازف طبول وقدماه، ومفتاح واحد بينهما. ووحدة تحكم ذات وسادات تعزف عليها أيدٍ واقعية، وتضيء كل وسادة لحظة ضربها. ولّد نمط طبول، أو اعزف نمطك الخاص وسجّله، أو أحضر MIDI الطبول من DAW لديك، وتعلّم العزف على الطبول بالأصابع وطقم الطبول من أول إيقاع حتى الإيقاعات الكاملة.","featuresPage.cards.songs.title":"أغانٍ كاملة وميكسر","featuresPage.cards.songs.body":"ابنِ أغنية يدويًا من مقاطعها أو ابدأ من توزيع فنان، ثم امزج كل جزء على قناته الخاصة، واسحبها إلى الخارج والمزج محفوظ فيها.","featuresPage.cards.drag.title":"اسحب ملف MIDI","featuresPage.cards.drag.body":"جزء واحد في كل مرة أو الأجزاء الأربعة معًا، تُسحب من النوتات مباشرةً إلى الـ DAW الخاص بك، أو تُحفظ كملف MIDI أو كملف PDF للنوتات.","featuresPage.cards.views.title":"عرض أمامي وعلوي وجانبي","featuresPage.cards.views.body":"بدّل بينها بينما تُعزف الموسيقى؛ تدور النوتات لتبقى مقروءة ولا تفوّت الأيدي أي نغمة.","featuresPage.cards.daw.title":"في أي DAW","featuresPage.cards.daw.body":"CLAP وVST3 على Windows وmacOS وLinux، وAU على macOS، وتطبيق مستقل للعمل بلا DAW.","featuresPage.cards.offline.title":"بلا اتصال، بلا ذكاء اصطناعي","featuresPage.cards.offline.body":"لا حساب، ولا قياس عن بُعد، ولا شبكة، ولا نموذج. كل جزء وكل توزيع للأصابع وكل حركة يأتي من قواعد.","featuresPage.compare.title":"جنبًا إلى جنب","featuresPage.compare.intro":"Freally Handscore 1.0 بجانب الأدوات التي يستخدمها الناس لكتابة الأجزاء الموسيقية أو لمشاهدة عزف البيانو. خانات المنتجات الأخرى مأخوذة من صفحاتها العامة ومن المراجعات، وقد رُوجعت في أكتوبر 2026؛ وحيث لم نتمكن من تأكيد أمر ما، تقول الخانة ذلك.","featuresPage.compare.feature":"الميزة","featuresPage.compare.row.generate":"يكتب أكوردات وألحانًا وخطوط باص جديدة بأساليب محددة بالاسم","featuresPage.compare.legend.yes":"متوفر","featuresPage.compare.legend.no":"غير متوفر","featuresPage.compare.row.plugin":"يعمل داخل الـ DAW الخاص بك كمكوّن إضافي","featuresPage.compare.row.hands":"يعرض أيديًا واقعية ثلاثية الأبعاد تعزف النغمات","featuresPage.compare.note.library":"مكتبته الخاصة من المقطوعات","featuresPage.compare.legend.part":"جزئيًا","featuresPage.compare.note.fingers":"أرقام الأصابع، بلا أيدٍ","featuresPage.compare.row.sheets":"يعرض النغمات كنوتة موسيقية","featuresPage.compare.legend.unknown":"غير مؤكَّد","featuresPage.compare.row.drag":"يسحب ملفات MIDI إلى الـ DAW الخاص بك","featuresPage.compare.row.offline":"يعمل بلا اتصال، وبلا ذكاء اصطناعي","featuresPage.compare.summaryTitle":"باختصار","featuresPage.compare.summary":"من بين هذه الأربعة، وحده Handscore 1.0 يملك كل الصفوف: أجزاء مكتوبة بأساليب محددة بالاسم، وأيدٍ واقعية تعزفها، والنوتة الموسيقية، والسحب إلى الـ DAW الخاص بك، والمكوّن الإضافي.","featuresPage.compare.theyWinTitle":"أين يتفوّقون","featuresPage.compare.theyWin":"Scaler 3 محطة عمل لنظرية الموسيقى أوسع بكثير. وSynthesia مصمَّم لتعلّم المقطوعات على لوحة مفاتيحك الخاصة؛ أما دروس Handscore فتستمع إليك وأنت تعزف بدءًا من الإصدار 0.6، لكن العزف المصاحب المباشر ينتظر الإصدار 1.9. ويضع AR Pianist عازفه في غرفتك بالواقع المعزَّز، وهو ما لا يفعله Handscore.","featuresPage.compare.fineprint":"Scaler وAR Pianist وSynthesia علامات تجارية لمالكيها، وهم غير مرتبطين بـ Freally Handscore. أخبرنا إن كانت خانة ما خاطئة وسنصحّحها.","featuresPage.why.title":"لماذا بُني بهذه الطريقة","featuresPage.why.rules.title":"قواعد لا نموذج","featuresPage.why.rules.body":"كل جزء وكل توزيع للأصابع وكل حركة يأتي من قواعد، بلا أي نموذج في أي مكان. الأسلوب نفسه والبذرة نفسها تعطي الأجزاء نفسها، في كل مرة.","featuresPage.why.drag.title":"ما تراه هو ما تسحبه","featuresPage.why.drag.body":"تُرسم النوتات من ملف MIDI الذي تسحبه، وتعزف الأيدي تلك النغمات بالضبط، لذا فما يصل إلى مسارك هو ما شاهدته.","featuresPage.why.real.title":"مبني بمقاسات حقيقية","featuresPage.why.real.body":"كل آلة مبنية بمقاساتها الحقيقية: لوحة المفاتيح بحجم بيانو حقيقي، وكل مفتاح يدور على نقطة ارتكازه كما يفعل المفتاح الحقيقي.","featuresPage.why.local.title":"يبقى على جهازك","featuresPage.why.local.body":"لا حساب ولا قياس عن بُعد ولا سحابة. لا يتصل المكوّن الإضافي ولا التطبيق المستقل بالإنترنت أبدًا، وتفشل بوابة بناء إذا أُضيفت يومًا شيفرة شبكة.","featuresPage.coming.title":"ما الذي لم يأتِ بعد","featuresPage.coming.intro":"نقولها بوضوح، لأن قائمة ميزات تخفي ثغراتها لا تستحق القراءة. تصف هذه الصفحة الإصدار 1.0، ويُبنى Handscore إصدارًا بعد إصدار، لذا فمعظم ما فيها لم يُبنَ بعد. كل إصدار على الطريق إلى 1.0 موسوم بحالته.","featuresPage.limits.title":"ما لا يفعله الإصدار 1.0","featuresPage.limits.export":"الأغنية التي يطابق لحنُها إحدى الكلاسيكيات أو لحنًا معروفًا لا يغادر منها Handscore سوى أكورداتها.","featuresPage.limits.families":"يعزف البيانوهات ووحدة التحكم بالوسادات وطقم الطبول والغيتارات وغيتار الباص. وكل عائلة أخرى من الآلات تصل إصدارًا بعد إصدار بعد 1.0، حتى الفرقة الكاملة في 2.0.","featuresPage.limits.learn":"تستمع دروسه إليك وأنت تعزف، لكن الأيدي لا تتبعك مباشرةً بعد: العزف المصاحب على أي آلة يصل في الإصدار 1.9.","featuresPage.coming.downloads":"لا توجد تنزيلات قبل الإصدار 1.0، ولا شيء منها على هذه الصفحة.","docs.intro":"ينمو Handscore ليصبح يدين واقعيتين على كل عائلة من الآلات، مع دروس موسيقية من البيانو إلى العزف بالأصابع على الوسادات وكتابة الأغاني وتوزيعها. ويكبر هذا الدليل معه إصدارًا بعد إصدار. وهو يغطّي الآن ما يفعله الإصدار 0.12.0: البيانوهات واليدان، والعزف على الطبول بالأصابع على وحدة التحكم بالوسادات، وآلة الطبول، وطقم الطبول وعازفه، وخريطة الطبول، والعروض الثلاثة، وتوليد أغنية، والنوتات، والسحب والتصدير، والمحرّر، والقطع الكلاسيكية، وشريط النقل، والدروس ودوراتها الاثنتا عشرة، والاستماع إلى آلة حقيقية أو إلى صوتك، والموالف، والمازج، ومحرّر الأغلفة، وآلاتك الخاصة، وعرض الأغنية وأدوات كتابة الأغاني فيه، ودرجة جاهزية النجاح.","docs.start.title":"البدء","docs.agreement.title":"اتفاقية الترخيص","docs.stage.title":"المسرح","docs.pianos.title":"البيانوهات","docs.play.title":"العزف على المفاتيح","docs.hands.title":"اليدان","docs.pads.title":"العزف على الطبول بالأصابع","docs.machine.title":"آلة الطبول","docs.kit.title":"طقم الطبول","docs.drummap.title":"خريطة الطبول","docs.views.title":"العروض","docs.generate.title":"توليد أغنية","docs.sheets.title":"النوتات","docs.tray.title":"صينية النوتات","docs.drag.title":"إلى DAW لديك","docs.edit.title":"تعديل النغمات","docs.lyrics.title":"كلمات الأغاني","docs.seeds.title":"البذور والسجل","docs.classics.title":"الكلاسيكيات","docs.transport.title":"شريط التشغيل","docs.lessons.title":"الدروس","docs.listen.title":"الاستماع","docs.mixer.title":"المازج","docs.envelopes.title":"محرّر الأغلفة","docs.hosted.title":"آلاتك الخاصة","docs.song.title":"عرض الأغنية","docs.songtools.title":"أدوات كتابة الأغاني","docs.grade.title":"درجة جاهزية النجاح","docs.shortcuts.title":"اختصارات لوحة المفاتيح","docs.project.title":"مشروعك","docs.theme.title":"الوضعان الفاتح والداكن","docs.language.title":"اللغات","docs.privacy.title":"خصوصيتك","docs.start.p1":"يعمل Handscore داخل الـ DAW الخاص بك كآلة موسيقية من نوع CLAP أو VST3 أو AU، أو بمفرده كتطبيق مستقل. ضعه على مسار آلة موسيقية.","docs.start.p2":"لا توجد تنزيلات قبل الإصدار 1.0.0، والشيفرة المصدرية خاصة.","docs.agreement.p1":"عند فتح Handscore لأول مرة، يعرض اتفاقية الترخيص الخاصة به. وحتى تختار «أوافق»، لا يفعل Handscore شيئًا ولا يُصدر أي صوت.","docs.agreement.p2":"تُحفظ إجابتك على جهازك وتشترك فيها كل نسخة مفتوحة من Handscore، في كل DAW وفي التطبيق المستقل. إذا رفضت، تبقى الاتفاقية على الشاشة، جاهزةً متى وافقت.","docs.stage.p1":"أسفل الشريط العلوي يقع المسرح: البيانو الذي اخترته بمفاتيحه الـ88، من A0 إلى C8، بمقاسات بيانو حقيقي، يملأ عرض النافذة. اسم كل مفتاح مكتوب على واجهته — على المفاتيح البيضاء بحبر داكن، وعلى السوداء بالأبيض — ويختفي ما دام المفتاح مضغوطًا، فترى دائمًا أي النغمات تُعزف.","docs.stage.p2":"إذا لم يستطع جهازك الرسم بالأبعاد الثلاثية، يقول المسرح ذلك ويشرح كيفية تفعيله، بدلًا من ألا يعرض شيئًا.","docs.stage.p3":"يقيس Handscore مدى سرعة جهازك في رسم المسرح، ويستقر على الجودة التي يستطيع الحفاظ عليها بسلاسة.","docs.pianos.p1":"يعتلي المسرحَ واحدٌ من أربعة بيانوهات في كل مرة: Grand Piano وAcoustic Piano وUpright Piano وHonky-Tonk Piano، لكلٍّ منها شكله وطلاؤه وصوته.","docs.pianos.p2":"يفتح زر «اختر الوضع» أعلى اليمين (أو P) خياراتك حسب الفئة. ضمن «الآلات»، يعزف زر «معاينة» جملة قصيرة على بيانو دون التبديل إليه، ويضعه زر «اختيار» على المسرح بانتقال تدريجي من البيانو السابق. يُحفظ اختيارك مع مشروعك.","docs.play.p1":"انقر على مفتاح لتسمعه، أو مرّر المؤشر فوق المفاتيح لتعزفها واحدًا تلو الآخر. ينخفض كل مفتاح دائرًا على نقطة ارتكازه، وكلما عُزف بقوة أكبر كان أسرع، ويخفت اسمه ما دام منخفضًا ثم يعود حين يرتفع.","docs.play.p2":"يعزف MIDI القادم من DAW لديك على البيانو ويحرّك مفاتيحه. وتُبقي دواسة الاستدامة النغمات التي تتركها حتى ترفع قدمك عنها.","docs.hands.p1":"تعزف يدان واقعيتان كل نغمة على المسرح كما يفعل عازف البيانو: كل إصبع مختار للمقطع، والإبهام يمرّ من تحت اليد في السلّم الموسيقي، والأكوردات الواسعة تُطال، وترتفع يدٌ فوق الأخرى حين تتطلّب الموسيقى تقاطع اليدين. وحين لا يُعزف شيء، تستريحان على المفاتيح متأهبتين.","docs.hands.p2":"يحدّد Handscore أي يد تعزف كل نغمة، وبأي إصبع، قبل أن تُعزف الموسيقى، فتصل اليدان لحظة انخفاض المفاتيح.","docs.pads.p1":"اختر وحدة التحكم بالوسادات من «اختر الوضع» ضمن «الآلات»، أو شغّل «وحدة تحكم الوسادات على المسرح» في تبويب «الطبول»: تعتلي المسرحَ وحدةُ تحكم ذات ست عشرة وسادة، وتعزف عليها اليدان طبول الحلقة إصبعًا إصبعًا — السبّابتان أولًا، وكل يد تلزم جانبها — بينما تبقى الأجزاء الأخرى مسموعة. تضيء كل وسادة لحظة ضربها بلون قطعة الطبول الخاصة بها، ويزداد سطوعها كلما اشتدّت الضربة، ثم يخبو ضوؤها كضوء وسادة حقيقية؛ ومع «تقليل الحركة» تبقى الألوان ويختفي الخفوت. ويحتفظ مشروعك بهذا الاختيار.","docs.pads.p2":"لكل حلقة طبولها الخاصة، تُكتب معها حين تضغط توليد. يعرض تبويب «الطبول»، بعد «خط الباص»، وساداته الست عشرة: انقر عليها، أو اعزفها من وحدة تحكم بالوسادات أو من لوحة مفاتيح عبر MIDI، أو شغّل «المفاتيح تعزف الوسادات» واعزفها من مفاتيح الحاسوب — 1 2 3 4 و Q W E R و A S D F و Z X C V، بدءًا بالصف العلوي. يضع التخطيط «الافتراضي» نغمات General MIDI من 36 إلى 51 على الوسادات بدءًا من أسفل اليسار؛ ويعكس «الأداء» الكيك والسنير والهاي هات ليدين اثنتين. يربط «تعلُّم» وحدة التحكم الخاصة بك: اضرب كل وسادة حين يطلبها، بالعدّ من أسفل اليسار. يلغي Esc، ويعيدك «نسيان» إلى الإعداد الافتراضي الشائع.","docs.pads.p3":"للطبول نوتتها الخاصة بتدوين الطبول القياسي، كل قطعة على خطها أو فراغها، ونغمات اليدين بسيقان إلى أعلى ونغمات القدمين بسيقان إلى أسفل. ومع وحدة التحكم بالوسادات على المسرح تقف أولًا على الحامل، ومع تشغيل أرقام الأصابع تُظهر كل نغمة يدها وإصبعها.","docs.pads.p4":"لتعزف طبولك الخاصة وتسجّلها، اضغط «تسجيل» في تبويب «الطبول». بعد العدّ التمهيدي تُعزف الحلقة، وفي كل مرة تعود فيها إلى بدايتها يصبح ما عزفته طبقةً تواصل العزف معها: كيك، ثم سنير، ثم الهاي هات. يزيل «تراجع عن الدورة» آخر طبقة، ويحتفظ «إيقاف» بالتسجيلة، مُحاذاةً إلى أجزاء الستة عشر إن كان «تكميم» مفعّلًا. ويحتفظ مشروعك بكل تسجيلة مع مدى دقتها على النبضة: اختر أيًّا منها، أو عُد إلى «طبول الحلقة الأصلية».","docs.pads.p5":"تعلّمه دورة «قرع الطبول بالأصابع» في وضع الدروس من اليوم 1، على آلة الطبول: يظهر نمط التمرين في خطواته تحت المسرح، وتتوهّج الوسادات التالية قبل موعدها، وتومض الوسادة الخاطئة بالأحمر، وتخبرك كل محاولة بمقدار تقدّمك على النبضة أو تأخّرك عنها. وتُسمع ضرباتك عبر وسادات آلة الطبول، ومنها عيّناتك الخاصة. ولا تُقيَّم النبرات والنغمات الشبحية إلا في محاولة عُزفت على وسادات تستشعر قوة ضربها، لا بالفأرة ولا بمفاتيح الحاسوب.","docs.machine.p1":"تبويب «الطبول» آلة طبول. في الأعلى يختار المفتاح ما يعزف الطبول، وتختار قائمة «طقم الأصوات» أحد أطقم Handscore الإلكترونية الأربعة — Sub وFloor وNeon وWire — أو طقم الأسلوب نفسه. وعلى اليسار تعرض «الضربات المفردة» أصوات الطقم وأصواتك الخاصة: انقر أحدها لتسمعه، واسحبه إلى وسادة (ومع Alt يصبح طبقة أخرى). والوسادات الست عشرة في الوسط، و«الحلقات» على اليمين تضم طبول الحلقة الأصلية والتسجيلات التي عزفتها، ويمنح «الطابع» الطقمَ كله «التشبّع» و«الطقطقة» و«النبرة» و«التهشيم».","docs.machine.p2":"اختر وسادة لتفتح صوتها في الأسفل. للوسادة حتى أربع طبقات، تُختار حسب قوة الضغط أو بالتناوب، لكلٍّ منها عيّنتها وكسبها وتوزيعها وضبطها وبدايتها. تُرسم العيّنة موجةً بمقابض لقصّ بدايتها ونهايتها ولإدخالها وإخراجها بالتلاشي، ويغيّر «عكس» و«تسوية المستوى» طريقة عزفها، لا الملف أبدًا. ثم يأتي ضبط الوسادة وغلاف حدّتها، وغلاف شدّتها، ومرشّح تمرير منخفض أو تمرير مرتفع أو تمرير نطاق بغلافه الخاص، وكسبها وتوزيعها، ومجموعة كتم (تُسكت الضربةُ الوساداتِ الأخرى في مجموعتها، كما يقطع الهاي هات المغلق الهاي هات المفتوح)، و«كتم» و«منفرد». تُسمع كل تغييرة فورًا وهي خطوة تراجع واحدة؛ ويعيد «أعد إلى صوت الطقم» إلى الوسادة صوت الطقم الأصلي.","docs.machine.p3":"يضع «أضف عيّنات…» أصواتك الخاصة في «الضربات المفردة»، وتذهب إليها أيضًا الملفات الصوتية التي تسحبها من متصفح الملفات: WAV أو AIFF أو FLAC، بطول يصل إلى 30 ثانية. ويُرفض الملف الطويل جدًا أو الكبير جدًا أو الصامت أو غير الصوتي مع ذكر السبب. ويحتفظ Handscore بنسخته الخاصة، فيعزف مشروعك العيّنة حتى لو نُقل الملف، ويسرد «التصدير إلى PDF» العيّنات التي يستخدمها المشروع.","docs.machine.p4":"يعرض مُتسلسِل الخطوات تحت صوت الوسادة طبول الحلقة خطواتٍ، صفًّا لكل وسادة وست عشرة خطوة في كل مازورة. انقر خطوة لتضع ضربة أو تمسحها، واسحب عبرها للرسم، واسحب بالزر الأيمن لإزالة الضربات واسحب عائدًا لإرجاعها، واضبط شدّة كل ضربة في الشريط أسفلها. ويؤخّر «السوينغ» أجزاء الستة عشر الواقعة بين النبضات، من 50 إلى 75 %. ومن المفاتيح: الأسهم للتنقّل، وEnter يضع أو يمسح، وDelete يمسح، وPage Up وPage Down يغيّران الشدّة. والطبول التي كتبها «توليد» والتسجيلات التي عزفتها تصل إلى الخطوات، وكل تعديل يُسمع ويُرى ويُسحب فورًا.","docs.kit.p1":"مفتاح واحد يختار ما يعزف طبولك: آلة الطبول أو طقم الطبول. تجده أعلى تبويب «الطبول»، وعلى مسار «الطبول» في المازج، وبجانب الطبول في صينية النوتات. والتبديل أثناء عزف الموسيقى لا يوقفها أبدًا: تُسمع الضربة التالية على الآخر، وإن كانت الطبول على المسرح انساب المسرح من وحدة التحكم بالوسادات إلى الطقم أو العكس. تُعزف الضربات نفسها في الحالتين، ويحتفظ مشروعك بالاختيار، ويعزف السحب الصوتي ما اخترته.","docs.kit.p2":"حين تكون الطبول على المسرح والطقم مختارًا، يقف هناك طقم محترف — سنير، وكيك، وتومان معلّقان وتومان أرضيان، وهاي هات، وصنجا كراش، وصنج رايد، وصنج سبلاش، وصنج صيني، وجرس بقر — ويدا عازف الطبول تمسكان العصوين وقدماه على الدوّاسات. كل ضربة تقع حيث يضربها عازف الطبول: اليد اليمنى متقاطعة نحو الهاي هات والرايد، والتمارين الأساسية والحشوات بالتناوب بين اليدين، والكيك تحت القدم اليمنى والهاي هات تحت اليسرى، والكعب مرفوع للنبرة، ودوّاسة مزدوجة فقط حين لا تستطيع قدم واحدة المواكبة. ويُعزف الجاز والبالاد بالفُرَش، والأساليب الأكوستيكية الهادئة بعصيّ الحِزم. وتلين جلود الطبول تحت العصي، وتتأرجح الصنوج ثم تستقر.","docs.kit.p3":"للطقم صوته الأكوستيكي الخاص، يُسمع عبر الميكروفونات القريبة والعلوية وميكروفونات الغرفة: وتمزجها منزلقات «الطابع» الثلاثة. وحين يعزف الطقم، تُظهر نوتة الطبول توزيع الضربات — R أو L على نغمة كل يد، وRF أو LF على نغمة كل قدم — مع رسم ضربة العصا المتقاطعة وضربة الحافة برؤوس نغمات خاصة بهما، والنغمة الشبحية بين قوسين، ومع الطقم على المسرح تقف أولًا على الحامل. أما أصوات الوسادات التي تغيّرها في هذه الأثناء فهي أصوات آلة الطبول، وتسمعها حين تعود إليها.","docs.drummap.p1":"اسحب ملف MIDI طبول من متصفح الملفات إلى تبويب «الطبول» فيصبح طبول الحلقة، كل نغمة كما جاءت. وتعرض «خريطة الطبول» بجانبه كل نغمة يستخدمها الملف، وعدد ضرباتها، وما تعزفه. ويختار «القراءة حسب» التخطيط الذي كتبه به DAW لديك — General MIDI أو Ableton Drum Rack أو FL Studio FPC أو Logic Drummer أو EZdrummer / Superior Drummer أو Addictive Drums — ويمكن ضبط كل صف على أي قطعة من الطقم، أو على «ليست في الطقم»، أو على خط الباص 808. ويعزف عازف الطبول كل تغيير فورًا. ويحفظ «احفظ كإعداد مسبق» خريطةً خاصة بك على هذا الحاسوب للملف التالي، ويحتفظ مشروعك بالخريطة التي يستخدمها.","docs.views.p1":"شاهد المسرح من الأمام أو من الأعلى أو من الجانب. أدِر مقبض العرض في الزاوية العلوية اليمنى من المسرح، أو اضغط V للعرض التالي وShift+V للعرض السابق. تنساب الكاميرا من عرض إلى التالي والموسيقى مستمرة، ويبقى كل مفتاح وكل يد وكل نغمة مضيئة على الإيقاع تمامًا. يتذكّر مشروعك العرض.","docs.views.p2":"الأمامي هو منظر العازف، ولوحة المفاتيح تملأ النافذة. العلوي ينظر مباشرة إلى المفاتيح واليدين: يغلق البيانو الكبير غطاءه لذلك، وتستلقي النوتات على الغطاء متجاورة مسطّحة لتقرأها؛ وفي البيانو العمودي تستلقي على غطائه العلوي. الجانبي ينظر على امتداد لوحة المفاتيح من طرف النغمات الحادة، على ارتفاع المفاتيح، ليُظهر شكل اليدين — كيف ينحني كل إصبع وإلى أي عمق ينزل كل مفتاح — والنوتات على الحامل مستديرة نحوك. وفي العرض الجانبي ينظر مفتاح من اليسار تحت مقبض العرض من طرف النغمات الغليظة بدلًا من ذلك. انقر على نوتة، أو اضغط من 1 إلى 6، لتراها عن قرب في أي عرض.","docs.generate.p1":"تبحث اللوحة اليسرى (يُظهرها تبويبها على حافة النافذة ويخفيها) بين 73 نوعًا موسيقيًا و1,507 فنانين و833 منتجًا. اختر واحدًا واضغط توليد أو G: تُكتب أربعة أجزاء — الأكوردات واللحن واللحن المضاد وخط الباص — بذلك الأسلوب، بطول 4 أو 8 مازورات، وتعزفها اليدان على البيانو.","docs.generate.p2":"تضبط الأزرار المجاورة لتوليد المقام والسلّم (41 خيارًا) والمزاج والإيقاع (من 20 إلى 999 نبضة في الدقيقة؛ اسحب الرقم لأعلى أو لأسفل) ودرجة التعقيد و4 أو 8 مازورات، ويعرض كلٌّ منها ما صُنعت به الأغنية. في DAW، يكتب اتبع DAW بإيقاع مشروعك، وما دام مفعّلًا يبقى زر الإيقاع على ذلك الإيقاع: أوقفه لتضبط إيقاعك الخاص. ولا يوجد اتبع DAW في التطبيق المستقل. يوزّع قابل للعزف الأجزاء لليدين؛ ويبقيها خام تمامًا كما كُتبت.","docs.sheets.p1":"يُطبع كل جزء صفحةَ نوتة على حامل نوتة البيانو، بعنوانه ورقم صفحته، وتقف بجوارها مدوّنة كاملة لكل الأجزاء. يضيء رأس كل نغمة لحظة عزفها تحت مؤشر تشغيل متحرك، ويقلب الجزء الطويل صفحاته أثناء العزف. انقر على صفحة، أو اضغط من 1 إلى 6، لتقريبها؛ ويعيدك Esc.","docs.tray.p1":"تحت المسرح تحمل الصينية كل جزء مع منفرد وكتم وقفل وتسجيلة جديدة. يبقى الجزء المقفل عندما تولّد من جديد. تقدّم التسجيلة والحلم 1–3 وإعادة الحلم ثلاث نسخ جديدة لجزء بجوار النسخة التي لديك: اختر واحدة واحتفظ بها.","docs.drag.p1":"اسحب جزءًا من صفحته، أو الأغنية كاملة عبر اسحب الكل، مباشرة إلى DAW لديك بصيغة MIDI. يحفظ التصدير ملف MIDI لجزء أو للأغنية كاملة في ملف تسمّيه أنت، مع شدّة كل نغمة، ومستوى كل جزء وتوزيعه بين اليمين واليسار، والإيقاع، والميزان.","docs.drag.p2":"يكتب التصدير إلى PDF النوتات مع صفحة غلاف: العنوان والإيقاع والمقام والسلّم والمدة والمازورات وعدد النغمات الإجمالي ولكل جزء ولكل صفحة، والآلات. أضف أسماء المشاركين — الكتّاب والمغنّين والمنتجين والعيّنات التي استخدمتها ومصادرها وشركة الإنتاج — مع اقتراح الأسماء أثناء الكتابة.","docs.edit.p1":"في الأعلى المسرح واللحن والأكوردات واللحن المضاد وخط الباص. يفتح تبويب الجزء لفافة البيانو الخاصة به، مع نقطة كتم وزر منفرد و× يُفرغ الجزء. حدّد النغمات وانقلها وأطِلها واحذفها وانسخها والصقها واستنسخها؛ وانقر بالزر الأيمن واسحب لإزالة النغمات وإعادتها. لكل جزء كسبه وتوزيعه الخاص.","docs.edit.p2":"سجّل من لوحة مفاتيح MIDI إلى اللفافة بعد عدٍّ تمهيدي لمازورة أو اثنتين. اطوِ اللفافة على سلّم الأغنية أو على الصفوف التي تحتوي نغمات: تُلوَّن صفوف السلّم وتُعلَّم النغمة الخارجة عنه. أثناء الرسم تُقترح النغمة أو الأكورد التالي بشكل باهت؛ يحتفظ به Tab، وتحتفظ النقرة بواحد، والرسم في مكان آخر يمحو الاقتراحات.","docs.edit.p3":"شغّل الأكوردات بجانب شريط النقل فيعزف مفتاح واحد أكوردًا من 3 أو 4 أو 5 نغمات في مقام الأغنية، من الفأرة أو لوحة مفاتيح الحاسوب أو لوحة مفاتيح MIDI.","docs.lyrics.p1":"اكتب الكلمات تحت اللحن أو اللحن المضاد مع تعليم المقاطع، فتُطبع على النوتة وتضيء عند غنائها. يبيّن عدّاد بجانب كل سطر هل يتّسع لمازورته. أثناء الكتابة يُقترح باقي الكلمة (يقبله Tab) ويُصحَّح الخطأ الإملائي، إلا إذا نقرت علامة الصح أو ضغطت Shift+Tab للاحتفاظ بكلمتك.","docs.seeds.p1":"يعرض كل توليد بذرته، ويعرض كل جزء بذرة تسجيلته، مع زر نسخ. الصق بذرة أغنية لتصنعها من جديد، أو بذرة تسجيلة جزء لاستعادة تلك التسجيلة. يمرّ رجوع وتقدّم بكل توليد صنعته، يعود كلٌّ منها كما كان تمامًا ويبقى محفوظًا بعد إعادة التشغيل؛ ولا يكرّر التوليد الجديد أي توليد قديم أبدًا.","docs.classics.p1":"تضم «الكلاسيكيات» في «اختر الوضع» اثنتين وستين أغنية من الملكية العامة للتعلّم: أغاني أطفال، وأغاني عيد الميلاد وتراتيله، وأغانٍ شعبية، وترانيم روحية وأناشيد، وألحانًا كلاسيكية، ومقطوعات بيانو محبوبة. كلٌّ منها موزّعة لليدين، اللحن في اليمنى والأكوردات في اليسرى. ابحث بالعنوان أو المؤلف، ثم اختر «تشغيل».","docs.classics.p2":"القطعة الكلاسيكية للتعلّم لا للأخذ: لا يخرج من Handscore إلا أكورداتها. الأغنية المولّدة التي يطابق لحنها أو لحنها المضاد أو خط الباص فيها لحنًا مشهورًا تُبقي ذلك الجزء داخل التطبيق وتوضّح السبب.","docs.transport.p1":"أسفل المسرح: الترجيع، والتشغيل أو الإيقاف المؤقت، والإيقاف، والتقديم السريع، وخط زمني يعرض زمن الأغنية وعلامة عند كل مازورة. مرّر المؤشر فوق الخط الزمني لترى اليدين في تلك اللحظة في معاينة صغيرة؛ وانقر أو اسحب للانتقال إليها. اضغط مطوّلًا على الترجيع أو التقديم السريع للتنقّل بسرعة. وفي الحالتين تسمع كل نغمة تمرّ بها. يشغّل مفتاح المسافة ويوقف مؤقتًا، وتنقلك مفاتيح الأسهم على الخط الزمني مازورةً واحدة.","docs.transport.p2":"حرف M بجانب المفاتيح هو المترونوم. شغّله فتحدّد نقرةٌ كل نبضة، والأولى من كل مازورة أعلى، بينما تُظهر نقطتاه النبضة.","docs.transport.p3":"عندما تكون للأغنية كلمات، تعرض معاينة الخط الزمني الكلمات التي تُغنّى في تلك اللحظة.","docs.lessons.p1":"اختر الوضع ← الدروس يفتح وضع الدروس داخل الاستوديو: خريطة الدورة وخطوات اليوم على اليسار، والمسرح في الوسط، ونص الدرس تحته. يختار زر «الدورة» فوق الخريطة دورةً من اثنتي عشرة دورة: البيانو، وقراءة النوتة، والإيقاع، وتدريب الأذن، والنظرية للمنتجين، وكتابة الأغاني، وكتابة الكلمات، والراب والتدفق، وتوزيع الأغنية، والمزج، وقرع الطبول بالأصابع، وطقم الطبول. تمضي كل دورة يومًا بعد يوم عبر أقسامها، وكل يوم جلسة موجَّهة، مع يوم للمراجعة كل أسبوع؛ وتمتد دورة البيانو من المبتدئ (الأيام من 1 إلى 90) مرورًا بالأساسي (من 91 إلى 400) حتى المتوسط (من 401 إلى 1,300)، وتمتد دورتا قرع الطبول بالأصابع وطقم الطبول من المبتدئ (الأيام من 1 إلى 30) حتى الأساسي (من 31 إلى 150). في المرة الأولى تُفتح الدورة على اليوم 1؛ وبعدها يعيدك زر متابعة مباشرةً إلى الدورة واليوم والخطوة والكلمة حيث توقفت. ويمكن فتح أي يوم من الخريطة، والخروج من الدروس يعيدك إلى الأغنية التي تركتها.","docs.lessons.p2":"كل خطوة تقرأ أو تعرض أو تستمع. شاهد: تعزف اليدان التمرين في العرض الذي تسمّيه الخطوة، ببطء إن طُلب ذلك، مع أرقام الأصابع. جرّب: تضيء المفاتيح المطلوبة وتنتظرها الموسيقى. على الإيقاع: بالسرعة المحددة بعد عدّ تمهيدي، وتُقاس كل نغمة على النبضة. اعزف كاملًا: اعزفها حتى النهاية، مع ملخّص في الختام. تسمّي كل محاولة المازورة والنبضة وتقدّم التصحيح. تُجتاز الخطوة بعد بضع محاولات صحيحة متتالية، ويُجتاز اليوم حين يُعزف تمرينه الرئيسي كاملًا، وعلى الإيقاع إن كان اليوم يعزفه على الإيقاع. للتمرين، كرّر بضع مازورات في حلقة، أو اعزف بيد واحدة بينما يعزف المسرح الأخرى، أو غيّر السرعة؛ وعلى سلّم السرعة ترتفع النبضة بعد ثلاث محاولات نظيفة وتنزل درجة بعد ثلاثة أخطاء. يعمل جرّب أيضًا بالفأرة على مفاتيح المسرح؛ أما على الإيقاع واعزف كاملًا فيحتاجان إلى لوحة مفاتيح MIDI، أو إلى تشغيل «الاستماع».","docs.lessons.p3":"القراءة بصوت عالٍ مطفأة حتى تشغّلها. عندها يقرأ صوت حاسوبك نفسه الدرس، وتضيء كل كلمة لحظة نطقها. مفتاح المسافة يشغّل ويوقف مؤقتًا، و⏹ يوقف، والضغط المطوّل على ⏪ أو ⏩ يرجع أو يتقدّم؛ اضبط السرعة من النصف إلى الضعف واختر الصوت من الأصوات المثبّتة. تعرض الساعات الوقت الذي قضيته في هذا اليوم وفي الأيام كلها، وعدد الأيام التي تمرّنت فيها. يبقى تقدّمك على هذا الحاسوب، هو نفسه في التطبيق المستقل وفي كل DAW، ولا يدخل أي مشروع أبدًا.","docs.lessons.p4":"يطرح تدريب الأذن سؤالًا واحدًا في كل مرة: يعزفه المسرح مرة واحدة، فتجيب على المفاتيح، ثم يأتي السؤال التالي. وفي دورة الإيقاع تختفي نقرة المترونوم على مراحل، من كل نبضة إلى لا شيء، حتى تحافظ على الإيقاع وحدك. وتعرض «النظرية للمنتجين» أي أغنية مولَّدة في مخطط Nashville بالأرقام.","docs.lessons.p5":"للدورات الإبداعية خطوات صنع: تعمل في عرض الأغنية، أو في شريط الكلمات أو شبكة التدفق فيه، أو في المازج، أو على صفحة من الدفتر، ويقول «افحص» ما وجده مقابل كل هدف من أهداف الخطوة، بلغة كاتب الأغاني أو مهندس الصوت. والهدف الذي خالفته عن قصد يمكن تعليمه بـ«علّمه مقصودًا»، فيُجتاز عندها. تعمل هذه الدروس على أغنيتك التعليمية الخاصة، المحفوظة مع تقدّمك، وعلى حلقات الدروس: فحين تغادر وضع الدروس تجد أغنية مشروعك ومزجه تمامًا كما كانا.","docs.lessons.p6":"تضع دورة «طقم الطبول» الطقمَ على المسرح، وتُعزف على طقم طبول إلكتروني عبر MIDI، أو على طقم أكوستيكي مع تشغيل «الاستماع»، أو بالفأرة ومفاتيح الحاسوب: مسكة العصا والضربة، والتمارين الأساسية من الضربات المفردة حتى الدحرجات، والقدمان، والباك بيت، والنغمات الشبحية، والهاي هات المفتوح والرايد، والشافل والسوينغ، والفُرَش، والدوّاسة المزدوجة، والحشوات والأشكال الكاملة، والإيقاعات من الروك والفانك إلى الوان دروب والبوسا نوفا والجاز، مع نقرة مترونوم تختفي على مراحل. وتعود طبول مشروعك وآلته حين تغادر.","docs.listen.p1":"تستطيع الدروس أن تسمع آلة حقيقية أو صوتك. اضغط L أو زر «الاستماع» في الشريط العلوي لتفتح نافذة «الاستماع»: اختر المدخل وقناته، أو كل القنوات ممزوجة، وراقب مستواه يتحرّك وأنت تعزف، مع ضوء للتشبّع واسمِ الأكورد الذي تعزفه على الأوتار. وإن لم يصل شيء، تقول النافذة ذلك، وتقول على Windows وmacOS أين تسمح بالميكروفون. سماعات الرأس تساعد: الدروس تسمعك أنت، لا مكبّرات الصوت.","docs.listen.p2":"في DAW، يستمع Handscore عبر مدخل السايد تشين الخاص به، «Listen»، وتبقى مخارجه كما هي. لا يُسمع شيء حتى يُرسَل إليه مسار: وتبيّن النافذة كيف يتم ذلك في Ableton Live وFL Studio وReaper.","docs.listen.p3":"لكل دورة تستطيع الاستماع مفتاح «الاستماع» في شريط الدرس، مطفأ حتى تشغّله. عندها تسمع دورات البيانو وقراءة النوتة والنظرية نغماتك وأكورداتك في «جرّب» و«على الإيقاع» و«اعزف كاملًا» وفي الأسئلة؛ وتسمع دورة «طقم الطبول» الكيك والسنير والهاي هات في طقم أكوستيكي وتقيس توقيت كل قطعة أخرى؛ وتقيس تمارين «الإيقاع» و«الراب والتدفق» توقيت تصفيقك أو طرقاتك أو مقاطعك مقارنةً بنقرة المترونوم؛ ويتلقّى «تدريب الأذن» إجاباتك غناءً، في أي أوكتاف. والمحاولة المسموعة بهذه الطريقة تُقيَّم على النغمات والتوقيت، وتقول ذلك: أما اللمسة والدوّاسة ومدة إمساك النغمة فلا تُقيَّم إلا عبر MIDI. وما دام «الاستماع» مشغّلًا، تبقى مفاتيح MIDI لديك تُصدر صوتًا لكنها لا تُقيَّم.","docs.listen.p4":"في خطوات شبكة التدفق في «الراب والتدفق»، يعزف زر «أدِّ الراب» الأغنية بعد عدّ تمهيدي بينما تؤدّي الراب فوقها؛ توقّف، فيُقاس توقيت محاولتك مقارنةً بالمقاطع التي وضعتها: كم منها سُمع، وتموضعك في الإيقاع، ومدى تبكير كل مقطع أو تأخّره.","docs.listen.p5":"يعرض موالف النافذة النغمة وكم سنتًا هي أعلى أو أخفض، ثابتًا ما دامت ترنّ، مع A4 في أي موضع من 415 إلى 466 Hz، وأسماء الأوتار المطلقة للغيتار والباص. وتقيس «المعايرة» المدة التي يستغرقها الصوت ليخرج من Handscore ويعود إليه، عبر حلقة راجعة بكابل أو من مكبّرات الصوت إلى الميكروفون، أو بالعزف المرافق مع نقرة المترونوم، لكي يقع ما تعزفه على الإيقاع؛ ويُحفظ الرقم لذلك المدخل على هذا الحاسوب.","docs.listen.p6":"كل شيء يُسمع على هذا الحاسوب، وفقط ما دام الضوء الذي يحمل كلمة «يستمع» مضاءً. لا يُسجَّل شيء ولا يُحفظ ولا يُرسَل: لا يحتفظ Handscore إلا بإعدادات الاستماع لديك، مثل المدخل الذي اخترته وزمن تأخّره.","docs.mixer.p1":"اضغط M، أو تبويب المازج، لترى مسارات كل الأجزاء جنبًا إلى جنب مع المسار الرئيسي. لكل مسار منزلق، ومقبض توزيع، وEQ بثلاثة نطاقات، والغرفة والصدى والحرارة، وضاغط (مطفأ حتى تشغّله)، ومقبض حُبيبي، مع مقياس مستوى LED وضوء تشبع؛ وللمسار الرئيسي منزلقه ومقبض حُبيبي ومقياسه الخاص. اسحب المنزلق مع Shift لحركات دقيقة، أو انقر عليه نقرًا مزدوجًا لضبطه على 0 dB. ينساب الكتم والمنفرد بدل أن ينقطعا؛ وCtrl+click على زر منفرد يضيف إليه جزءًا. تُسمع كل تغييرة أثناء تحريكها وتصبح خطوة تراجع واحدة حين تفلتها، ويحتفظ المشروع بالمزج.","docs.mixer.p2":"تحت النوتات، يسحب زر السحب الصوتي في كل جزء ذلك الجزءَ إلى DAW لديك كملف WAV، مطبوعًا عبر مساره بإيقاع الأغنية؛ ويُسحب المزج الكامل كما تسمعه ويسمّي الأجزاء التي يستبعدها. أما سحب MIDI فيحمل منزلق الجزء وتوزيعه كأدوات تحكّم، ويذكر ما لا يستطيع MIDI حمله.","docs.envelopes.p1":"في تبويب الجزء، يفتح زر الأغلفة أغلفة الجزء: مستوى الصوت والمرشّح وحدّة النغمة والتوزيع والحُبيبي، وكلٌّ منها مطفأ حتى تشغّله. اسحب نقطة، أو اسحب معيّن المقطع لتثنيه؛ انقر نقرًا مزدوجًا لإضافة نقطة، أو على نقطة لإزالتها؛ اختر نقطة لتكتب قيمها، أو حرّكها بمفاتيح الأسهم. لكل غلاف عمق، ومقياس زمن، وتتبّع لقوة الضغط والمفتاح، وتكرار مُمسَك، وأزمنة مقفلة على الإيقاع، وإعادة إطلاق أو متّصل أو إعادة ضبط مع كل مازورة، ومزج A/B. ابدأ من شكل جاهز، وانسخ غلافًا إلى جزء آخر، وتراجع وأعد، أو أعد ضبط الكل؛ وأثناء عزف الأغنية تسير نقطة لكل نغمة على المنحنى.","docs.hosted.p1":"يمكن لكل جزء أن يعزف بإحدى آلاتك الخاصة بصيغة VST3 أو CLAP بدلًا من آلة Handscore. في تبويب الجزء أو مساره في المازج، يفتح زر الآلة قائمة الاختيار: آلة Handscore نفسها أولًا، ثم كل آلة عثر عليها الفحص في مجلدات المكوّنات الإضافية القياسية وفي المجلدات التي تضيفها. اختر واحدة فيعزف الجزء من خلالها، ونافذتها على بُعد نقرة؛ ويحتفظ المشروع بالمكوّن الإضافي وصوته. يعمل كل مكوّن إضافي في عملية خاصة به، فإذا تعطّل أحدها توقف وحده، ويُعوَّض زمن تأخّره. تبقى اليدان على آلة Handscore، ويُسحب ذلك الجزء بصيغة MIDI. وإذا ذكر مشروعك مكوّنًا إضافيًا غير موجود على هذا الحاسوب، حلّت محلّه آلة Handscore نفسها، ويخبرك الجزء بذلك. في هذا الإصدار تُفتح نوافذ المكوّنات الإضافية على Windows.","docs.song.p1":"اضغط A، أو تبويب التوزيع، لتفتح الخط الزمني للأغنية تحت المسرح: يبقى البيانو واليدان والنوتات أمامك وأنت تبني، وتُعزف الأغنية ما دام التبويب مفتوحًا، أو من أي تبويب عند عزلها منفردة. يعطي «ولّد أغنية» أغنية الأسلوب كاملة في شكلها الخاص؛ اختر أحد أشكاله أو شكله الفارغ، أو ابدأ أغنية فارغة، أو اسحب أسلوبًا من اللوحة اليسرى إلى الخط الزمني. كل صف جزء، والطبول في الأخير، وكل خانة مقطع.","docs.song.p2":"أضف الأقسام وأدرجها وانقلها وأعد تسميتها وأطلها وقصّرها من رؤوسها وقوائمها؛ انسخ المقاطع والصقها، واجعل مقطعًا مشتركًا مستقلًا، وأدخل المقطع وأخرجه بتلاشٍ من زواياه، وحدّد عدد الموازير التي يكررها، واقفل المقاطع التي تحتفظ بها اللقطة الجديدة. أعد توليد قسم، أو كرره بـ ↻، أو انقر مرتين على مقطع لتسمعه وحده. املأ خانة بإرسال الحلقة التي على المسرح إليها، أو بإفلات ملف .mid أو ملف صوتي عليها من متصفح الملفات في اللوحة اليسرى، أو بعزف لقطة فيها على لوحة مفاتيح MIDI. يفتح الرمز ✎ في المقطع نغماته في محرر الجزء تحت الخط الزمني، حيث يغيّر كل تعديل كل قسم يشترك في المقطع. كل تغيير خطوة واحدة من التراجع.","docs.song.p3":"تعلّم النوتات كل قسم وتقلب صفحاتها أثناء عزف الأغنية، ويقلبها «انتقل إلى قسم» في الدرج كلها إلى هناك. اسحب الأغنية كاملة مع أقسامها علامات، أو قسمًا من مقبض رأسه، أو مقطعًا من مقبضه الخاص، بصيغة MIDI أو صوتًا، إلى برنامجك الموسيقي. تعطي «إعادة الحلم» ثلاث نسخ جديدة من الأغنية كلها، ويعمل «تصدير MIDI» و«تصدير إلى PDF» من عرض الأغنية أيضًا.","docs.songtools.p1":"في تبويب التوزيع، يضع زر «شريط الكلمات» كلمات الأغنية تحت اللحن، مقطعًا تحت كل نغمة: تُعلَّم المقاطع المنبورة، وتُلوَّن أواخر الأسطر بحسب قوافيها، ويُوسَم كل قسم بنظام قافيته، وتُميَّز العبارات الشائعة. ويفتح زر «شبكة التدفق» شبكة الراب: مقاطع كل مازورة على أجزائها من ستة عشر، والقوافي ملوّنة، والعدد بجانب كل مازورة، ومدى بُعد الكلمات عن الشبكة.","docs.songtools.p2":"أعطِ الأغنية عنوانًا فوق كلماتها. يحفظ زر «النسخ» الأغنية باسمٍ ويبيّن ما تغيّر منذ ذلك: الكلمات سطرًا سطرًا، والأقسام التي أُضيفت أو حُذفت أو نُقلت أو أُعيدت تسميتها أو تغيّر طولها، والنغمات التي كسبها كل جزء أو فقدها. وتُطفئ قائمة القسم جزءًا فيه ثم تعيد تشغيله، ويبيّن رأس كل قسم طاقته. وفي الدرس، يطبع «ملف الأعمال» ورقة اللحن برموز أكورداتها وكلماتها، وورقة الكلمات، وتقرير الحرفة في ملف PDF واحد.","docs.grade.p1":"يفتح زر «جاهزية النجاح» في تبويب التوزيع درجة الأغنية بجانب الخط الزمني: حرف ودرجة من 100 من اثني عشر فحصًا على شكلها وأجزائها وكلماتها، يقول كل منها ما وجده وما يرمي إليه. اكتب كلمات اللحن في خانتها، سطرًا لكل مازورة من المازورة 1، لتُقيَّم أيضًا. إنها قائمة تحقق لكاتب الأغاني تُقاس على نغمات الأغنية نفسها، وتُطبع على غلاف ملف PDF.","docs.shortcuts.p1":"اضغط ? أو مفتاح الاختصارات في الشريط العلوي لترى كل الاختصارات.","docs.project.p1":"حفظ مشروعك في DAW يحفظ الأغنية وتعديلاتها ومزجها وكلماتها والبيانو والعرض وأسماء المشاركين، وعند إعادة الفتح يعود كل شيء كما كان.","docs.theme.p1":"مفتاح «السمة الداكنة» أعلى اليسار يجعل النافذة فاتحة أو داكنة. يتذكّر Handscore اختيارك، وكذلك تفعل تطبيقات Freally الأخرى على جهازك.","docs.language.p1":"يتحدث Handscore ثماني عشرة لغة ويبدأ بلغة نظامك.","docs.privacy.p1":"لا يستخدم المكوّن الإضافي ولا التطبيق المستقل الشبكة أبدًا. إذا توقّف Handscore يومًا على نحو غير متوقع، يُحفظ تقرير قصير على جهازك ويُعرض عليك في المرة التالية التي يُفتح فيها؛ ولا يُرسَل شيء ما لم تختر الإبلاغ عنه.","docs.privacy.p2":"حين يستمع درس، أو يظهر الموالف، أو تجري معايرة، يُحلَّل ما يسمعه Handscore على حاسوبك ولا يُسجَّل ولا يُحفظ ولا يُرسَل أبدًا، ويُعلمك ضوء حين يكون مستمعًا.","kit.skip":"الانتقال إلى المحتوى","kit.nav.site":"الموقع","kit.nav.home":"الرئيسية","kit.nav.features":"الميزات","kit.nav.documentation":"التوثيق","kit.nav.changelog":"سجل التغييرات","kit.nav.language":"اللغة","kit.nav.allApps":"كل تطبيقات Freally","kit.badge.progress":"v0.12.0 منجز · v0.13.0 هو التالي","kit.cta.features":"شاهد كل الميزات","kit.cta.docs":"اقرأ التوثيق","kit.price":"Freally Handscore مجاني اليوم، لكنه قد لا يبقى مجانيًا إلى الأبد: قد تُباع الإصدارات المستقبلية.","kit.noDownloads":"لا توجد تنزيلات بعد، والشفرة المصدرية خاصة.","kit.label.overview":"نظرة عامة","kit.label.inside":"في الداخل","kit.label.roadmap":"خارطة الطريق","kit.ladder.done":"منجز","kit.ladder.planned":"مخطط له","kit.ladder.goal":"الهدف","kit.ladder.later":"لاحقًا","kit.label.honesty":"الصراحة","kit.family.label":"عائلة Freally","kit.family.title":"<span class=\"hl-muted\">عائلة واحدة.</span> <span class=\"hl-bright\">عشرة تطبيقات.</span>","kit.cta.label":"ما الذي تغيّر","kit.cta.title":"<span class=\"hl-muted\">كل إصدار،</span> <span class=\"hl-bright\">مدوَّن.</span>","kit.cta.lede":"يسرد سجل التغييرات كل ما تغيّر في Freally Handscore، إصدارًا بعد إصدار، بثماني عشرة لغة.","kit.cta.changelog":"اقرأ سجل التغييرات","kit.footer.thisApp":"هذا التطبيق","kit.footer.family":"عائلة Freally","kit.status.devVersion":"قيد التطوير · v0.12.0","kit.head.features":"<span class=\"hl-muted\">كل ما يفعله،</span> <span class=\"hl-bright\">جنبًا إلى جنب.</span>","kit.label.numbers":"بالأرقام","kit.numbers.lead":"كل رقم محسوب من التطبيق نفسه. لا شيء مُقدَّر، ولا شيء مُقرَّب إلى الأعلى.","kit.label.free":"مجاني اليوم","kit.label.compare":"مقارنة","kit.label.principles":"المبادئ","kit.label.limits":"الحدود","kit.states.title":"ماذا تعني الحالات","kit.states.done":"مبنيّ وموسوم، لكنه ليس تنزيلًا على هذا الموقع","kit.states.planned":"لم يُبنَ بعد","kit.states.goal":"الإصدار الذي يقود إليه الطريق","kit.states.later":"بعد ذلك، ولم يُجدوَل بعد","kit.states.ladder":"شاهد كل درجة على الطريق","kit.head.documentation":"<span class=\"hl-muted\">كيف يعمل،</span> <span class=\"hl-bright\">خطوة بخطوة.</span>","kit.search.placeholder":"ابحث في التوثيق","kit.docs.contents":"المحتويات","kit.head.changelog":"<span class=\"hl-muted\">كل تغيير،</span> <span class=\"hl-bright\">إصدارًا بعد إصدار.</span>","kit.changelog.lede":"الأحدث أولًا: كل ما تغيّر في Freally Handscore، بكل لغة يتحدث بها هذا الموقع.","kit.changelog.versions":"الإصدارات","kit.search.none":"لا شيء في هذا الموقع يطابق ذلك.","kit.zoom.close":"إغلاق","changelog.83ccac5ded77":"<span class=\"release__meta\"><span class=\"release__ver\">v0.12.0</span><time class=\"release__date\" datetime=\"2026-10-19\">2026-10-19</time></span>","changelog.9cc20e44893e":"الاستماع المباشر. صارت الدروس تسمع آلة حقيقية وصوتًا حقيقيًا الآن: شغّل «الاستماع» لدورة ما، فتسمع دورة البيانو البيانو الأكوستيكي لديك عبر ميكروفون، ودورة طقم الطبول الكيك والسنير والهاي هات في طقمك الأكوستيكي، و«الراب والتدفق» مقاطعك على النبضة، وتدريب الأذن الإجابات التي تغنّيها — وتُقيَّم على النغمات والتوقيت، كما مع مفاتيح MIDI. وفي نافذة «الاستماع» موالف ومعايرة لزمن التأخّر. كل شيء يُسمع على حاسوبك، وفقط ما دام الضوء مضاءً، ولا يُسجَّل شيء ولا يُحفظ ولا يُرسَل.","changelog.6b02e0d363a4":"الإضافات","changelog.bf779e7e1025":"<strong>نافذة «الاستماع».</strong> اضغط L أو زر «الاستماع» في الشريط العلوي: اختر المدخل وقناته (أو كل القنوات، ممزوجة)، وراقب مستواه وضوء التشبّع فيه، وشاهد اسم الأكورد الذي تعزفه على الأوتار، واعرف فورًا حين لا يصل شيء، مع المكان الذي تسمح فيه بالميكروفون على Windows وmacOS. في DAW، يستمع Handscore عبر مدخل السايد تشين الخاص به، «Listen»، ومخارجه الرئيسية دون تغيير، وتبيّن النافذة كيف ترسل إليه مسارًا في Ableton Live وFL Studio وReaper.","changelog.8f4dc2184742":"<strong>الضوء.</strong> يظهر ضوء يحمل كلمة <em>يستمع</em> في الشريط العلوي وشريط الدرس وشبكة التدفق ما دام المدخل مفتوحًا بالضبط، وعندها فقط. لا يُفتح المدخل إلا ما دام درس يستمع، أو يظهر الموالف، أو تجري معايرة، ويُغلق في غضون ثوانٍ من مغادرة الدرس أو إغلاق النافذة أو التوقف.","changelog.a25a986acc4c":"<strong>دروس تسمعك.</strong> لكل دورة تستطيع الاستماع مفتاح «الاستماع»، مطفأ حتى تشغّله. تسمع دورات البيانو وقراءة النوتة والنظرية نغمات بيانو أكوستيكي أو أي آلة أخرى وأكورداتها، في «جرّب» و«على الإيقاع» و«اعزف كاملًا» وفي الأسئلة، بالفحوص والملاحظات نفسها كما عبر MIDI، مع وسم <em>التقييم بالأذن</em>: النغمات والتوقيت، لا اللمسة ولا الدوّاسة ولا مدة إمساك النغمة أبدًا. ويُحتسب الأكورد بأسماء نغماته، ولا يُحسب ما يعزفه المسرح عزفًا لك.","changelog.5c5bfa0fb63d":"<strong>طقم الطبول عبر الميكروفون.</strong> تسمع دورة طقم الطبول الكيك والسنير والهاي هات في طقم أكوستيكي، وتُسمع ضربة الكيك مع الهاي هات على أنها الاثنتان معًا، وتقيّم كل قطعة أخرى بتوقيتها.","changelog.10606f858c8b":"<strong>«الراب والتدفق» والإيقاع بالصوت.</strong> تقيس تمارين «الإيقاع» و«الراب والتدفق» توقيت مقاطعك أو تصفيقك أو طرقاتك مقارنةً بنقرة المترونوم، ويقيس <em>أدِّ الراب</em> في شبكة التدفق توقيت محاولة راب مؤدّاة مقارنةً بالمقاطع التي وضعتها، مبكّرة أو متأخّرة، فتسمع تموضعك في الإيقاع. لا يُتعرَّف على شيء: لا على كلمة ولا على صوت.","changelog.a77396ec8a04":"<strong>تدريب الأذن غناءً.</strong> غنِّ إجابتك: تُحتسب في أي أوكتاف، فيستطيع الصوت المنخفض أن يغنّيها أوكتافًا أدنى.","changelog.9b71e7aedb2c":"<strong>الموالف.</strong> النغمة وكم سنتًا هي أعلى أو أخفض، ثابتًا ما دامت النغمة ترنّ، مع A4 من 415 إلى 466 Hz، وأسماء الأوتار المطلقة للغيتار والباص.","changelog.48248965431c":"<strong>معايرة زمن التأخّر.</strong> تقيس «المعايرة» المدة التي يستغرقها الصوت ليخرج من Handscore ويعود إليه، عبر حلقة راجعة بكابل أو من مكبّرات الصوت إلى الميكروفون، أو بالعزف المرافق مع نقرة المترونوم، وتحفظ الرقم لذلك المدخل على هذا الحاسوب، لكي يقع ما تعزفه على الإيقاع.","changelog.6e1e7067accb":"<span class=\"release__meta\"><span class=\"release__ver\">v0.11.0</span><time class=\"release__date\" datetime=\"2026-10-19\">2026-10-19</time></span>","changelog.1208381835ec":"آلة الطبول وطقم الطبول. صار تبويب «الطبول» الآن آلة طبول حقيقية: ضع عيّناتك الخاصة على وساداتها، ورتّبها طبقات، وشكّل صوت كل وسادة، وبرمج إيقاعك خطوةً خطوة. أو بدّل الطبول إلى طقم أكوستيكي كامل وشاهد يدي عازف طبول وقدميه تعزف إيقاعك، كل ضربة حيث يعزفها عازف طبول حقيقي. ومفتاح واحد ينقلك بينهما أثناء عزف الموسيقى، والضربات نفسها في الحالتين. ويُقرأ MIDI الطبول المستورد عبر خريطة طبول تضبطها صفًّا صفًّا، وتعلّم دورة طقم الطبول الطقمَ من أول ضربة لك حتى الأغاني الكاملة في الأيام من 1 إلى 150.","changelog.7c23af602295":"<strong>آلة الطبول.</strong> ست عشرة وسادة، لكلٍّ منها حتى أربع طبقات حسب قوة الضغط أو بالتناوب، وضبطها الخاص، وغلاف الحدّة، وغلاف الشدّة، ومرشّح بغلافه الخاص، والكسب، والتوزيع، ومجموعة الكتم، والكتم، والمنفرد. قصّ العيّنة، وأضف إليها التلاشي، واعكسها، وسوِّ مستواها، واضبط كسبها دون تغيير الملف. كل تغييرة خطوة تراجع واحدة وتُسمع فورًا.","changelog.89b709b63ac0":"<strong>أطقم Handscore الخاصة.</strong> أربعة أطقم إلكترونية — Sub وFloor وNeon وWire — في كلٍّ منها كل صوت تستخدمه الطبول، بثلاث طبقات لقوة الضغط ونسختين تتناوبان، وتبدأ طبول كل أسلوب على الطقم الذي يناسبه. ويمنح «التشبّع» و«الطقطقة» و«النبرة» و«التهشيم» الطقمَ طابعه.","changelog.257fba39181e":"<strong>عيّناتك الخاصة على الوسادات.</strong> أفلت ملف WAV أو AIFF أو FLAC من متصفح الملفات على وسادة، أو أضف واحدًا عبر <em>أضف عيّنات…</em>. ويُرفض الملف الطويل جدًا أو الكبير جدًا أو الصامت أو غير الصوتي مع ذكر السبب. ويحتفظ Handscore بنسخته الخاصة، فيعزف المشروع حتى لو نُقل الأصل، وتُدرج عيّناتك في «التصدير إلى PDF».","changelog.6b00189bd87e":"<strong>مُتسلسِل الخطوات.</strong> صف خطوات لكل وسادة على امتداد مازورات الحلقة، 4 أو 8: انقر خطوة، وارسم عبر الخطوات، واسحب بالزر الأيمن للمسح واسحب عائدًا للاستعادة، واضبط شدّة كل ضربة، وأضف السوينغ إلى الضربات الواقعة بين النبضات. ويصل إليه النمط الذي كتبه «توليد» والتسجيلات التي عزفتها، وكل تعديل يُسمع ويُرى ويُسحب فورًا.","changelog.354397d3cc08":"<strong>طقم الطبول.</strong> طقم محترف على المسرح — سنير، وكيك، وتومان معلّقان وتومان أرضيان، وهاي هات، وصنجا كراش، ورايد، وسبلاش، وصنج صيني، وجرس بقر — ويدا عازف الطبول تمسكان العصوين وقدماه على الدوّاسات. كل ضربة تقع حيث يضربها عازف الطبول: اليد اليمنى متقاطعة نحو الهاي هات، والتمارين الأساسية والحشوات بالتناوب بين اليدين، والكيك والهاي هات تحت القدمين، ودوّاسة مزدوجة فقط حين لا تستطيع قدم واحدة المواكبة. الفُرَش للجاز والبالاد، وعصيّ الحِزم للأساليب الأكوستيكية الهادئة. وله صوته الأكوستيكي الخاص، مع ميكروفونات قريبة وعلوية وميكروفونات للغرفة يمكنك مزجها.","changelog.f0b2a589c2a6":"<strong>آلة الطبول أو طقم الطبول.</strong> مفتاح واحد في تبويب «الطبول»، وعلى مسار «الطبول»، وبجانب الطبول في الصينية، يختار أيّهما يعزف طبولك. والتبديل أثناء عزف الأغنية لا يوقفها أبدًا: تُسمع الضربة التالية على الآخر، وينتقل المسرح إليه. ويحتفظ مشروعك بالاختيار، ويعزف السحب الصوتي ما اخترته.","changelog.ae274e274c50":"<strong>خريطة الطبول.</strong> يحتفظ MIDI الطبول القادم من DAW لديك بكل صف كما جاء. اختر تخطيط DAW لديك (General MIDI، Ableton Drum Rack، FL Studio FPC، Logic Drummer، EZdrummer / Superior Drummer، Addictive Drums) أو اضبط كل صف على قطعة من الطقم، أو على <em>ليست في الطقم</em>، أو على خط الباص 808، فيعزفه عازف الطبول فورًا. واحفظ خرائطك الخاصة.","changelog.5929431e1824":"<strong>دورة طقم الطبول.</strong> الأيام من 1 إلى 150 في وضع الدروس على طقم طبول إلكتروني عبر MIDI: مسكة العصا والضربة، والضربات المفردة والمزدوجة، والبارادِدل، والفلام، والدراغ، والدحرجات، والقدمان، والباك بيت، والنغمات الشبحية، والهاي هات المفتوح والرايد، والشافل والسوينغ، والفُرَش وعصيّ الحِزم، والدوّاسة المزدوجة، والحشوات والأشكال، والإيقاعات من الروك والفانك إلى الوان دروب والبوسا نوفا والجاز، مع نقرة مترونوم تختفي على مراحل.","changelog.92e2bf5a0b9c":"<strong>قرع الطبول بالأصابع على آلة الطبول.</strong> صارت دورة قرع الطبول بالأصابع تعزف الآن عبر وسادات آلة الطبول، ونمط التمرين معروض بجانب المسرح.","changelog.df6470b1e841":"<span class=\"release__meta\"><span class=\"release__ver\">v0.10.0</span><time class=\"release__date\" datetime=\"2026-10-17\">2026-10-17</time></span>","changelog.6d2456347b5e":"العزف على الطبول بالأصابع. تعتلي المسرحَ وحدةُ تحكم بالوسادات، تضيء وساداتها الست عشرة مع كل ضربة، وتعزف عليها يدان واقعيتان طبول حلقتك إصبعًا إصبعًا. صار لكل حلقة الآن طبولها الخاصة، مطبوعةً على نوتة طبول. اعزف طبولك الخاصة وسجّلها على أي وحدة تحكم بالوسادات، طبقةً فوق طبقة كلما عادت الحلقة إلى بدايتها، واحتفظ بالتسجيلات التي تعجبك. وتعلّمه دورة قرع الطبول بالأصابع من أول إيقاع حتى الإيقاعات الكاملة.","changelog.9f50ff1513e0":"<strong>وحدة التحكم بالوسادات على المسرح.</strong> اخترها من «اختر الوضع» ضمن «الآلات»، أو شغّلها في تبويب «الطبول»: وحدة تحكم بوسادات 4×4، تعزف اليدان على وساداتها طبول الحلقة، السبّابتان أولًا، وكل يد تلزم جانبها. وتبقى الأجزاء الأخرى مسموعة. ويحتفظ مشروعك بهذا الاختيار.","changelog.e64037f005b8":"<strong>تضيء كل وسادة لحظة ضربها.</strong> لكل قطعة طبول لونها الخاص، وتحدّد قوة الضربة شدة توهّجها قبل أن يخبو، كضوء وسادة حقيقية. ومع «تقليل الحركة» تبقى الألوان ويختفي الخفوت.","changelog.766fe929f61e":"<strong>طبول في كل حلقة.</strong> صار التوليد يكتب طبول الحلقة أيضًا، من مولّدات الطبول في MIDI Master. ومع خط باص 808، يأتي الكيك والـ 808 نمطًا واحدًا، وتجلب تسجيلة جديدة لخط الباص طبولًا جديدة معها.","changelog.18971f931e55":"<strong>تبويب الطبول.</strong> ست عشرة وسادة على الشاشة، بعد تبويب خط الباص، مع نقطته وعلامة × الخاصة به. انقر عليها، أو اعزفها من وحدة تحكم MIDI، أو شغّل «المفاتيح تعزف الوسادات» واعزفها من مفاتيح الحاسوب (1 2 3 4 و Q W E R و A S D F و Z X C V). اختر التخطيط «الافتراضي» (نغمات General MIDI من 36 إلى 51 بدءًا من الوسادة السفلى اليسرى) أو تخطيط «الأداء» المعكوس. يربط «تعلُّم» وحدة التحكم الخاصة بك: اضرب كل وسادة حين تُطلب منك.","changelog.d30547a5121a":"<strong>نوتة الطبول.</strong> يُطبع جزء الطبول بتدوين الطبول القياسي، كل قطعة على خطها أو فراغها الخاص، ونغمات اليدين بسيقان إلى أعلى ونغمات القدمين بسيقان إلى أسفل. وتقف على الحامل مع النوتات الأخرى (أولًا، حين تكون وحدة التحكم بالوسادات على المسرح) ولها مفتاح رقمها مثلها، وهي في الصينية مع منفرد وكتم وفي ملف PDF. ومع تشغيل أرقام الأصابع تُظهر كل نغمة يدها وإصبعها.","changelog.5fcbc2452dda":"<strong>اعزف طبولك الخاصة وسجّلها.</strong> سجّل فوق الحلقة بعد عدّ تمهيدي: في كل مرة تعود فيها الحلقة إلى بدايتها، تصبح الدورة التي عزفتها طبقةً تواصل العزف معها، فتستطيع أن تضيف كيك، ثم سنير، ثم الهاي هات. يزيل «تراجع عن الدورة» آخر طبقة، ويحتفظ «إيقاف» بالتسجيلة، مُحاذاةً إلى أجزاء الستة عشر إن كان «تكميم» مفعّلًا. ويحتفظ مشروعك بكل تسجيلة مع مدى دقتها؛ اختر أيًّا منها، أو عُد إلى طبول الحلقة الأصلية.","changelog.d5b28d4df7b8":"<strong>دورة قرع الطبول بالأصابع.</strong> الأيام من 1 إلى 150 في وضع الدروس: السبّابتان، ثم الإبهامان والإصبعان الوسطيان، والباك بيت، ومواضع الكيك، والسوينغ، والنبرات والنغمات الشبحية، والحشوات، وإيقاعات الأنواع الموسيقية، والتمارين الأساسية للطبول على وسادة واحدة وعبر الوسادات، والثلاثيات والشافل، والإيقاعات الخطّية، مع نقرة مترونوم تختفي على مراحل. تتوهّج الوسادات التالية قبل موعدها، وتومض الوسادة الخاطئة بالأحمر، وتخبرك كل محاولة بمقدار تقدّمك على النبضة أو تأخّرك عنها. ولا تُقيَّم نبرات المحاولة التي تُعزف بالفأرة أو بمفاتيح الحاسوب.","changelog.2a6141e43be0":"التغييرات","changelog.bb31c9fcf9cb":"<strong>اتبع DAW متاح في برامج DAW فقط.</strong> لا يحتوي التطبيق المستقل على مفتاح اتبع DAW. وفي DAW، يبقى زر الإيقاع على إيقاع DAW ما دام اتبع DAW مفعّلًا؛ أوقفه لتضبط إيقاعًا خاصًا بك.","changelog.e77d5ee11f6c":"<strong>أزرار عنوان التوزيع.</strong> صارت أزرار تراجع وإعادة وكتم ومنفرد وزرّا التكبير والتصغير − و+ أيقوناتٍ صغيرة على سطر عنوان «التوزيع»، الذي يبقى ظاهرًا بينما تتمرّر الأزرار تحته. ويضيء كتم ومنفرد ما داما مفعّلين، ولكل زر لونه الخاص تحت المؤشر.","changelog.50f8bc668b74":"<span class=\"release__meta\"><span class=\"release__ver\">v0.9.0</span><time class=\"release__date\" datetime=\"2026-10-17\">2026-10-17</time></span>","changelog.48baf93edf6a":"دروس تتجاوز البيانو. تسع دورات جديدة تقف إلى جانب دورة البيانو في وضع الدروس: قراءة النوتة الموسيقية الحقيقية، والإيقاع، وتدريب الأذن، ونظرية الموسيقى للمنتجين بنظام Nashville Number System، وكتابة الأغاني، وكتابة الكلمات مع مسار للراب والتدفق، وتوزيع الأغنية، والمزج، وكلٌّ منها يومًا بعد يوم من الدرس الأول حتى نهاية قسمه الأساسي. أما دورة البيانو نفسها فتمتد الآن حتى الدرجة الخامسة تقريبًا. تُنجَز الدورات الإبداعية في عرض الأغنية، وعلى شريط الكلمات، وفي المازج، وتُفحص بقواعد الحرفة التي يمكنك تجاوزها؛ ويكتسب عرض الأغنية أدوات كاتب الأغاني التي تستخدمها هذه الدورات.","changelog.d6ab249214f0":"<strong>عشر دورات في وضع الدروس.</strong> منتقي دورات فوق الخريطة: البيانو، وقراءة النوتة، والإيقاع، وتدريب الأذن، والنظرية للمنتجين، وكتابة الأغاني، وكتابة الكلمات، والراب والتدفق، وتوزيع الأغنية، والمزج، ولكلٍّ منها أيامه المجتازة وموضعه وساعاته؛ ويفتح زر متابعة الدورة التي كنت فيها. لا يغيّر وضع الدروس مشروعك أبدًا: ما يحرّكه الدرس يُعاد إلى مكانه حين تغادر، والمشروع الذي يحفظه DAW لديك في منتصف الدرس يُحفظ كما كان.","changelog.3d47fd1323dd":"<strong>دورة البيانو حتى الدرجة الخامسة تقريبًا.</strong> الأيام من 401 إلى 1,300: كل مقام كبير وصغير بأصابعه الصحيحة، وسلالم بفارق ثالثة وسادسة، وأربيجات أكوردات السابعة، والنغمات من فئة السادس عشر، وقطع بصوتين، وقطع السوناتينا والرومانسية والجاز والثنائيات والمسرح يعزف معك، والعزف من الذاكرة، ومحطات تقييم عند الدرجات الثالثة والرابعة والخامسة تقريبًا.","changelog.7c030855b3fc":"<strong>قراءة النوتة.</strong> اسمعها قبل أن تراها، ومعالم المدرج، والخطوات والقفزات، ودلائل المقام، والخطوط الإضافية والأكوردات، وقراءة جديدة من النظرة الأولى كل يوم على مستواك، والورقة مطبوعة بمقام الموسيقى نفسه.","changelog.101d58d454d2":"<strong>الإيقاع.</strong> العدّ، وتقسيم النبضة حتى أجزاء الستة عشر والثلاثيات، والسنكوب، والسوينغ، والموازين المركّبة وغير المنتظمة، وتعدد الإيقاعات على مفتاح واحد أو مفتاحين، مع نقرة مترونوم تختفي على مراحل حتى تحافظ على الإيقاع وحدك.","changelog.9773ae1570b4":"<strong>تدريب الأذن.</strong> يعزف المسرح سؤالًا وتجيب على المفاتيح، سؤالًا واحدًا في كل مرة: أعلى أم أخفض، والمسافات، وكبير أم صغير، والأكوردات وانقلاباتها، والقفلات والتتابعات الهارمونية كخطوط باص، وألحان وإيقاعات تعيد عزفها كما سمعتها.","changelog.5fe00efe6b26":"<strong>النظرية للمنتجين.</strong> درجات السلّم، والمسافات، والأكوردات ووظائفها، والتتابعات، والأنماط (المودات)، ونظام Nashville Number System — أي أغنية مولَّدة تُعرض في مخطط بالأرقام، مع الموازير المقسومة والأكوردات المقدَّمة قبل وقتها.","changelog.bc8ada8b4e41":"<strong>كتابة الأغاني، وكتابة الكلمات، والراب والتدفق، وتوزيع الأغنية.</strong> يومًا بعد يوم من أغنيتك الأولى حتى اثنتي عشرة أغنية، في أنواع موسيقية كثيرة، تُنجَز في عرض الأغنية والدفتر وشريط الكلمات: يقول «افحص» في كل خطوة ما وجده وأين، وأي هدف خالفته عن قصد يمكن تعليمه بـ«علّمه مقصودًا».","changelog.71310f87543d":"<strong>المزج.</strong> ضبط مستويات الكسب، والتوازن، والتوزيع بين اليسار واليمين، وEQ، والضغط، والغرفة والصدى، والجهارة، على حلقات الدروس في المازج؛ ويطبع «افحص» الحلقة ويقيس ذراها وجهارتها وذروتها الحقيقية. ولا يغيّر أي درس مزج مشروعك أبدًا.","changelog.9373aa367a64":"<strong>أدوات كتابة الأغاني في عرض الأغنية.</strong> عنوان للأغنية؛ وشريط الكلمات تحت اللحن، كل مقطع تحت نغمته مع تعليم نبره، وأواخر الأسطر ملوّنة بحسب القافية وكل قسم موسوم بنظام قافيته؛ وتمييز العبارات الشائعة؛ وجزء يُطفأ في قسم واحد ثم يُعاد تشغيله؛ وطاقة كل قسم؛ ونسخ مسمّاة من الأغنية مع ما تغيّر منذ كلٍّ منها؛ وشبكة التدفق للراب؛ وملف أعمال PDF — ورقة اللحن برموز أكورداتها وكلماتها، وورقة الكلمات، وتقرير الحرفة.","changelog.b82b445328ca":"<span class=\"release__meta\"><span class=\"release__ver\">v0.8.0</span><time class=\"release__date\" datetime=\"2026-10-16\">2026-10-16</time></span>","changelog.578b5d28a79c":"عرض الأغنية. صار Handscore يكتب الأغاني كاملة ويبنيها ويعزفها، لا الحلقات وحدها: أنشئ أغنية كاملة في الشكل الخاص بأي أسلوب، أو ابنها قسمًا قسمًا على الخط الزمني في تبويب التوزيع، فتعزفها اليدان والنوتات من المازورة الأولى إلى الأخيرة وتقلب الصفحات أثناء العزف. للأغنية طبولها على مسار خاص بها، وتُسحب إلى برنامجك الموسيقي كاملة أو قسمًا قسمًا أو مقطعًا مقطعًا، وتأتي بدرجة جاهزية النجاح التي تبيّن، فحصًا بعد فحص، كيف تقف أمام القواعد العملية لكتابة الأغاني.","changelog.b62ffaa12ca0":"<strong>تبويب التوزيع.</strong> اضغط A: يرسو الخط الزمني للأغنية تحت المسرح، فيبقى البيانو واليدان والنوتات أمامك وأنت تبني، وتُعزف الأغنية ما دام التبويب مفتوحًا (أو عند عزلها منفردة من أي تبويب). أنشئ أغنية أسلوب كاملة، أو اختر أحد أشكاله أو شكله الفارغ، أو ابدأ أغنية فارغة، أو اسحب أسلوبًا من اللوحة اليسرى إلى الخط الزمني.","changelog.3711bc940735":"<strong>ابنِ أغنية بيدك.</strong> أضف الأقسام وأدرجها وانقلها وأعد تسميتها وأطلها وقصّرها؛ انسخ المقاطع والصقها، واجعل مقطعًا مشتركًا مستقلًا، وأدخل المقطع وأخرجه بتلاشٍ، وحدّد عدد الموازير التي يكررها، واقفل المقاطع التي تحتفظ بها اللقطة الجديدة. أعد توليد قسم، أو كرر قسمًا واحدًا، أو انقر مرتين على مقطع لتسمعه وحده. كل تغيير خطوة واحدة من التراجع.","changelog.3a48bd4ed77a":"<strong>املأ خانة على طريقتك.</strong> أرسل الحلقة التي على المسرح إلى قسم، أو أفلت ملف <code>.mid</code> أو ملفًا صوتيًا على خانة من متصفح الملفات الجديد (يتحول الصوت إلى نغمات)، أو اعزف لقطة في خانة على لوحة مفاتيح MIDI، مع التكميم إن شئت.","changelog.bcf7416c3978":"<strong>حرّر نغمات مقطع داخل الأغنية.</strong> يفتح الرمز ✎ في المقطع نغماته في محرر الجزء تحت الخط الزمني: اختر النغمات وانقلها وأطلها وارسمها وانسخها والصقها واحذفها في كل قسم يشترك في المقطع، أو اجعله مستقلًا لتغيّر قسمًا واحدًا. اعزف نغمات على لوحة مفاتيح MIDI بدءًا من المازورة التي تختارها.","changelog.bda265df4980":"<strong>النوتات واليدان عبر الأغنية كلها.</strong> تعلّم كل ورقة نوتة كل قسم بعد خط مازورة مزدوج وتعرض سكون الجزء مازورةً واحدة مع عددها؛ وبعد منتصف الصفحة ينقلب نصفها العلوي إلى الصفحة التالية، ويقلب <em>انتقل إلى قسم</em> كل الأوراق إلى هناك. تخطط اليدان حركاتهما عبر الأقسام، واليد التي لا تجد ما تعزفه ترتفع عن المفاتيح وتستريح.","changelog.6a41964e3d04":"<strong>صف الطبول.</strong> تُعزف طبول الأغنية على آلة إيقاع الأسلوب، على مسار خاص بها في المازج. في التوزيع القابل للعزف لا تحتفظ إلا بما تستطيع يدان وقدمان عزفه؛ ويحتفظ الخام بكل ضربة.","changelog.909f3c615e53":"<strong>أغنية إلى برنامجك الموسيقي.</strong> اسحب الأغنية كاملة مع أقسامها علامات، أو قسمًا وحده، أو مقطعًا واحدًا، بصيغة MIDI أو صوتًا (حتى 15 دقيقة). ويعمل تصدير MIDI والتصدير إلى PDF من عرض الأغنية أيضًا.","changelog.e1e1d7a49efa":"<strong>إعادة حلم الأغنية كلها.</strong> ثلاث نسخ جديدة من الأغنية بشكلها ومقامها وإيقاعها وميزانها، مع الاحتفاظ بمقاطعك المقفلة؛ احتفظ بالتي تعجبك.","changelog.9d5296c87435":"<strong>درجة جاهزية النجاح.</strong> حرف ودرجة من 100 من اثني عشر فحصًا على شكل الأغنية وأجزائها وكلماتها: كم مرة تعود اللازمة ومتى تصل، وطول المقدمة، والتباين بين الأقسام، والإيقاع المناسب للأسلوب، ومدى اللحن وخطه، وكيف تناسب الكلمات موازيرها وتتقفى وتتكرر. يقول كل فحص ما وجده وما يرمي إليه، فتُعلّمك الدرجة؛ اكتب كلمات اللحن في خانتها لتُقيَّم أيضًا. وهي على غلاف ملف PDF كذلك.","changelog.9960bf9700bd":"<span class=\"release__meta\"><span class=\"release__ver\">v0.7.0</span><time class=\"release__date\" datetime=\"2026-10-16\">2026-10-16</time></span>","changelog.89f5c24a8af1":"المازج. صار كل جزء يعزف الآن عبر مساره الخاص — منزلق، وتوزيع، وEQ، وغرفة، وصدى، وحرارة، وضاغط، ومقبض حُبيبي — إلى المسار الرئيسي، مع مقاييس المستوى والكتم والمنفرد، وكل ذلك محفوظ مع مشروعك. اسحب أي جزء، أو المزج كاملًا، إلى DAW لديك كصوت تمامًا كما تسمعه. شكّل صوت كل جزء بمحرّر الأغلفة، واعزف أي جزء بإحدى آلاتك الخاصة بصيغة VST3 أو CLAP.","changelog.8b1d7b62602b":"<strong>المازج.</strong> اضغط M: مسارات كل الأجزاء جنبًا إلى جنب مع المسار الرئيسي — منزلق بتدريج مطبوع يتبع مؤشرك، ومقياس مستوى LED مع ضوء التشبع، وشبكة المقابض (المنخفض، الأوسط، المرتفع، الغرفة، الصدى، الحرارة)، وضاغط مع ضوء خفض الكسب، والتوزيع، والمنفرد، والكتم. تُسمع كل حركة أثناء تحريكها، وتصبح خطوة تراجع واحدة حين تفلتها.","changelog.2869671be357":"<strong>كتم ومنفرد ينسابان.</strong> يخفت الجزء ويعود خلال 30 ms بدل أن ينقطع، ولا يُسمع في وضع المنفرد إلا الأجزاء المنفردة — Ctrl+click يضيف جزءًا آخر.","changelog.fcb6690799bd":"<strong>مقبض حُبيبي.</strong> على كل مسار وعلى المسار الرئيسي: من لا شيء عند 0 % إلى سحابة من الحُبيبات والأصداء وغلالة صوتية عند 100 %، صوت يحوّل أي جزء إلى أجواء محيطية. بذرته من المشروع، فيخرج الطبع متطابقًا في كل مرة.","changelog.57a83d56df21":"<strong>سحب الصوت.</strong> يسحب زر السحب الصوتي في كل جزء ذلك الجزءَ كملف WAV بدقة 24-bit، مطبوعًا عبر مساره بإيقاع الأغنية؛ ويُسحب المزج الكامل كما تسمعه ويسمّي الأجزاء التي يستبعدها.","changelog.b2176c506737":"<strong>سحب MIDI يحمل المزج.</strong> يدخل منزلق الجزء وتوزيعه إلى الملف بصفتهما CC 7 وCC 10، ويسرد زر السحب ما لا يستطيع MIDI حمله.","changelog.5b174d5cb7c6":"<strong>محرّر الأغلفة.</strong> أغلفة مستوى الصوت والمرشّح وحدّة النغمة والتوزيع والحُبيبي لكل مولّد، وكلٌّ منها مطفأ حتى تشغّله: نقاط للسحب، ومقاطع للثني، وتكرار مُمسَك، وأزمنة مقفلة على الإيقاع، وتتبّع قوة الضغط والمفتاح، وإعادة الإطلاق أو المتّصل، ومزج A/B، وأشكال بدء، ونسخ إلى جزء آخر، وتراجع وإعادة، ونقطة حيّة لكل نغمة تسير على المنحنى.","changelog.747aa74c96df":"<strong>آلاتك الخاصة.</strong> يمكن لكل جزء أن يعزف بإحدى آلاتك الخاصة بصيغة VST3 أو CLAP بدلًا من آلة Handscore: اخترها من تبويب الجزء أو مساره من بين الآلات التي يعثر عليها الفحص، وافتح نافذتها من هناك، فيحتفظ مشروعك بالمكوّن الإضافي وصوته. يعمل كل مكوّن إضافي في عملية خاصة به، فإذا تعطّل أحدها توقف وحده، ويُعوَّض زمن تأخّره. تبقى اليدان على آلة Handscore، ويُسحب ذلك الجزء بصيغة MIDI.","changelog.ddebf2581fd7":"<span class=\"release__meta\"><span class=\"release__ver\">v0.6.0</span><time class=\"release__date\" datetime=\"2026-10-16\">2026-10-16</time></span>","changelog.1d54e0107a4f":"الدروس. يعلّم Handscore الآن العزف على البيانو، يومًا بعد يوم، من أولى نغماتك حتى مستوى الصف الثاني تقريبًا: 400 يوم في قسمين، المبتدئ والأساسي، كل يوم منها جلسة موجَّهة قائمة بذاتها. تُريك اليدان كل تمرين من أي عرض، ثم يستمع إليك الدرس وأنت تعزف على لوحة مفاتيح MIDI ولا ينتقل إلى ما بعده إلا حين يكون العزف صحيحًا. شغّل القراءة بصوت عالٍ فيقرأ لك صوت حاسوبك نفسه الدرس، وتضيء كل كلمة لحظة نطقها.","changelog.7cf885e0b28b":"<strong>الدروس داخل الاستوديو.</strong> اختر الوضع ← الدروس يفتح دورة البيانو: خريطة الدورة وخطوات اليوم على اليسار، والمسرح في الوسط، ونص الدرس تحته. الخروج من الدروس يعيدك إلى الأغنية التي تركتها.","changelog.1c23de3f48f7":"<strong>400 يوم من البيانو.</strong> المبتدئ (الأيام 1–90) والأساسي (الأيام 91–400): الجلسة وشكل اليد، ووضعيات الأصابع الخمس، وقراءة المدرج الكبير، والإيقاع، والكوردات، والدواسة، والسلالم والأربيجات، واليدان معًا وقطع للعزف، مع يوم للمراجعة كل أسبوع وعودة ما تعلّمته من قبل حين يحين وقته.","changelog.1a00ed521da6":"<strong>الاستماع والتحقق بثلاث طرق.</strong> <em>جرّب</em>: تضيء المفاتيح المطلوبة وتنتظرها الموسيقى. <em>على الإيقاع</em>: بالسرعة المحددة بعد عدّ تمهيدي، وتُقاس كل نغمة على النبضة. <em>اعزف كاملًا</em>: اعزفها من البداية إلى النهاية، مع ملخّص في الختام.","changelog.93f77c21d390":"<strong>ملاحظات كملاحظات المعلّم.</strong> تسمّي كل محاولة المازورة والنبضة وتقدّم التصحيح — نغمة فائتة، مبكرة أو متأخرة، موصولة أو مفصولة، الدواسة — وتذكر ما أحسنتَ فيه.","changelog.03b65d4d96a6":"<strong>أدوات للتمرين.</strong> كرّر بضع مازورات في حلقة، واعزف بيد واحدة بينما يعزف المسرح الأخرى، واصعد سلّم السرعة (درجة إلى الأعلى بعد ثلاث محاولات نظيفة، ودرجة إلى الوراء بعد ثلاثة أخطاء)، وشاهد عروضًا بطيئة من أي عرض مع أرقام الأصابع. تتلاشى أسماء المفاتيح كلما حفظتها.","changelog.deb6f2d0e7f9":"<strong>القراءة بصوت عالٍ.</strong> مطفأة حتى تشغّلها، ويتذكّر Handscore اختيارك. يقرأ صوت حاسوبك الدرس، وتضيء الكلمة المنطوقة كما في شاشة الكاريوكي ويتمرّر النص ليبقيها ظاهرة. شغّل وأوقف مؤقتًا بمفتاح المسافة، وأوقف، واضغط مطوّلًا على ⏪ أو ⏩ للرجوع أو التقدّم، واضبط السرعة من النصف إلى الضعف واختر الصوت؛ وتعرض ساعة وقت القراءة المنقضي والمتبقي.","changelog.b9d693ff0bb1":"<strong>تقدّمك محفوظ.</strong> الأيام التي اجتزتها، والوقت الذي قضيته في كل درس وفيها كلها، والأيام التي تمرّنت فيها، بالأيام والساعات والدقائق والثواني — على هذا الحاسوب، في التطبيق المستقل وفي كل DAW. متابعة يفتح تمامًا حيث توقفت: اليوم والخطوة والكلمة.","changelog.2f7168838eb6":"<span class=\"release__meta\"><span class=\"release__ver\">v0.5.0</span><time class=\"release__date\" datetime=\"2026-10-15\">2026-10-15</time></span>","changelog.cb681d22c8c6":"العرض من الأعلى ومن الجانب. شاهد اليدين من الأمام أو من فوق مباشرة أو من الجانب، وانتقل بسلاسة من عرض إلى آخر والموسيقى تعزف — فلا تفوّت المفاتيح ولا اليدان ولا النغمات المضيئة نبضة واحدة. من الأعلى، يغلق البيانو الكبير غطاءه وتستلقي النوتات عليه مسطّحة جاهزة للقراءة؛ ومن الجانب يظهر شكل اليدين: كيف ينحني كل إصبع وإلى أي عمق ينزل كل مفتاح.","changelog.92ffe6279372":"<strong>ثلاثة عروض: أمامي وعلوي وجانبي.</strong> أدِر مقبض العرض في الزاوية العلوية اليمنى من المسرح، أو اضغط V للعرض التالي وShift+V للعرض السابق. يتذكّر مشروعك العرض.","changelog.51b3e3c98cbc":"<strong>انتقال بلا انقطاع.</strong> تنساب الكاميرا من عرض إلى التالي دون أن تخترق البيانو أبدًا، وتستمر الموسيقى أثناء الحركة: كل مفتاح وكل يد وكل نغمة مضيئة في موضعها تمامًا كما لو كانت الكاميرا ساكنة.","changelog.24e5e2980ffb":"<strong>علوي: المفاتيح واليدان من فوق.</strong> يطوي البيانو الكبير دعامته ويُسطّح حامل النوتة ويغلق غطاءه؛ ترتفع النوتات عن الحامل وتنتظر فوق المفاتيح ثم تستلقي متجاورة على الغطاء المغلق، مستقيمة تُقرأ من مكان جلوسك. وفي البيانو العمودي تستلقي النوتات على غطائه العلوي.","changelog.ea29eaefbaec":"<strong>جانبي: اليدان من الجانب.</strong> تنظر الكاميرا على امتداد لوحة المفاتيح من طرف النغمات الحادة، على ارتفاع المفاتيح — أو من طرف النغمات الغليظة، مع <em>من اليسار</em> تحت مقبض العرض — وتستدير النوتات على الحامل نحوها لتبقى مقروءة.","changelog.49ab9c89770a":"<strong>اليدان من كل جانب.</strong> تُلقيان ظلّهما على المفاتيح التي تعزفانها، ومن الأعلى لا يغوص طرف إصبع أبدًا في مفتاح أو في جسم البيانو.","changelog.31bd22333d53":"<strong>النوتة عن قرب في كل عرض.</strong> انقر عليها أو اضغط من 1 إلى 5؛ ويعيدك Esc إلى العرض.","changelog.7acb71645827":"<strong>سلاسة في كل عرض.</strong> بعد كل تغيير للعرض أو للبيانو، يتحقق Handscore من جديد من مدى سلاسة رسم المسرح، وإن تباطأ خفّض الجودة وأخبرك بذلك.","changelog.d524626e7e53":"<span class=\"release__meta\"><span class=\"release__ver\">v0.4.0</span><time class=\"release__date\" datetime=\"2026-10-15\">2026-10-15</time></span>","changelog.1afdc18898f2":"ولِّد واقرأ واسحب. ابحث بين 73 نوعًا موسيقيًا و1,507 فنانين و833 منتجًا، واضغط توليد، فتُكتب أربعة أجزاء — الأكوردات واللحن واللحن المضاد وخط الباص — بذلك الأسلوب وتعزفها اليدان على البيانو. يُطبع كل جزء نوتة موسيقية حقيقية على حامل النوتة في البيانو، بجوار مدوّنة كاملة، وتضيء كل نغمة لحظة عزفها. اسحب جزءًا، أو الأغنية كاملة، مباشرة إلى DAW لديك، وعدّل أي نغمة في لفافة البيانو الخاصة بها، وصدّر ملف MIDI أو ملف PDF للنوتات مع أسماء المشاركين.","changelog.e5fa15165f43":"<strong>التوليد بأي أسلوب.</strong> ابحث عن نوع موسيقي أو فنان أو منتج في اللوحة اليسرى (يُظهرها تبويبها على حافة التطبيق ويخفيها) واضغط توليد أو G. تضبط الأزرار المجاورة المقام والسلّم (41 خيارًا) والمزاج والإيقاع (من 20 إلى 999 نبضة في الدقيقة؛ اسحب الرقم لأعلى أو لأسفل) ودرجة التعقيد و4 أو 8 مازورات، ويعرض كلٌّ منها ما صُنعت به الأغنية. يكتب <em>اتبع DAW</em> بإيقاع مشروعك.","changelog.9b105b8264c8":"<strong>أربعة أجزاء تعزفها اليدان.</strong> الأكوردات واللحن واللحن المضاد وخط الباص، موزّعة لليدين (<em>قابل للعزف</em>) أو تمامًا كما كُتبت (<em>خام</em>). يملأ كل توليد مازوراته الأربع أو الثماني، والتبديل من 4 إلى 8 يكرّر المازورات الأربع الأولى.","changelog.99862da9695f":"<strong>نوتة موسيقية حقيقية.</strong> يُطبع كل جزء صفحةً على حامل النوتة، بعنوانه ورقم صفحته، وبجوارها مدوّنة كاملة لكل الأجزاء. يضيء رأس كل نغمة لحظة عزفها تحت مؤشر تشغيل متحرك، ويقلب الجزء الطويل صفحاته أثناء العزف. انقر على صفحة، أو اضغط من 1 إلى 5، لتقريبها؛ ويعيدك Esc.","changelog.4ed6b96e134b":"<strong>صينية النوتات.</strong> تحت المسرح، كل جزء مع منفرد وكتم وقفل وتسجيلة جديدة. يبقى الجزء المقفل عندما تولّد من جديد.","changelog.2b9c198c01ea":"<strong>اسحب إلى DAW لديك.</strong> اسحب جزءًا واحدًا، أو الأغنية كاملة عبر <em>اسحب الكل</em>، من صفحته إلى DAW لديك بصيغة MIDI.","changelog.471d0e4ba86d":"<strong>التصدير.</strong> احفظ ملف MIDI لجزء أو للأغنية كاملة، مع شدّة كل نغمة، ومستوى كل جزء وتوزيعه بين اليمين واليسار، والإيقاع، والميزان.","changelog.142257343a9f":"<strong>التصدير إلى PDF.</strong> ملف PDF للنوتات مع صفحة غلاف: العنوان والإيقاع والمقام والسلّم والمدة والمازورات وعدد النغمات الإجمالي ولكل جزء ولكل صفحة، والآلات. أضف أسماء المشاركين — الكتّاب والمغنّين والمنتجين والعيّنات التي استخدمتها ومصادرها وشركة الإنتاج — مع اقتراح الأسماء أثناء الكتابة.","changelog.1531fe3dfe30":"<strong>تبويب لكل جزء.</strong> في الأعلى المسرح واللحن والأكوردات واللحن المضاد وخط الباص؛ ولكل تبويب لفافة بيانو خاصة ونقطة كتم وزر منفرد و× يُفرغ الجزء.","changelog.dc61e3f5b735":"<strong>عدّل النغمات.</strong> حدّد النغمات وانقلها وأطِلها واحذفها وانسخها والصقها واستنسخها في لفافة أي جزء؛ وانقر بالزر الأيمن واسحب لإزالة النغمات وإعادتها. سجّل من لوحة مفاتيح MIDI إلى اللفافة بعد عدٍّ تمهيدي لمازورة أو اثنتين. لكل جزء كسبه وتوزيعه الخاص.","changelog.0cb3c4c9fd20":"<strong>السلالم على اللفائف.</strong> اطوِ اللفافة على سلّم الأغنية أو على الصفوف التي تحتوي نغمات؛ تُلوَّن صفوف السلّم وتُعلَّم النغمة الخارجة عنه.","changelog.0ef6f26c2429":"<strong>أكوردات بمفتاح واحد.</strong> شغّلها فيعزف مفتاح واحد أكوردًا من 3 أو 4 أو 5 نغمات في مقام الأغنية، من الفأرة أو لوحة مفاتيح الحاسوب أو لوحة مفاتيح MIDI.","changelog.d9cada2e85a6":"<strong>النغمات الشبحية.</strong> أثناء الرسم تُقترح النغمة أو الأكورد التالي بشكل باهت؛ يحتفظ به Tab، وتحتفظ النقرة بواحد، والرسم في مكان آخر يمحو الاقتراحات.","changelog.01aa58d9ab50":"<strong>كلمات الأغاني.</strong> اكتب الكلمات تحت اللحن أو اللحن المضاد مع تعليم المقاطع، فتُطبع على النوتة وتضيء عند غنائها. يبيّن عدّاد بجانب كل سطر هل يتّسع لمازورته. أثناء الكتابة يُقترح باقي الكلمة (يقبله Tab) ويُصحَّح الخطأ الإملائي، إلا إذا نقرت علامة الصح أو ضغطت Shift+Tab للاحتفاظ بكلمتك.","changelog.407e049442f6":"<strong>التسجيلة والحلم 1–3 وإعادة الحلم.</strong> ثلاث نسخ جديدة لأي جزء بجوار النسخة التي لديك؛ اختر واحدة واحتفظ بها. إعادة الحلم لقطعة كلاسيكية تحوّلها إلى أغنية جديدة خاصة بك.","changelog.a2ae6ec40472":"<strong>البذور.</strong> يعرض كل توليد بذرته وبذرة تسجيلة كل جزء، مع زر نسخ. الصق بذرة أغنية لتصنعها من جديد، أو بذرة تسجيلة جزء لاستعادة تلك التسجيلة.","changelog.7403cd98e6cb":"<strong>السجل.</strong> رجوع وتقدّم عبر كل توليد صنعته، يعود كلٌّ منها كما كان تمامًا ويبقى محفوظًا بعد إعادة التشغيل. لا يكرّر التوليد الجديد أي توليد قديم أبدًا.","changelog.3c500d42ebde":"<strong>القطع الكلاسيكية للتعلّم لا للأخذ.</strong> لا يخرج من القطعة الكلاسيكية إلا أكورداتها. الأغنية المولّدة التي يطابق لحنها أو لحنها المضاد أو خط الباص فيها لحنًا مشهورًا تُبقي ذلك الجزء داخل التطبيق وتوضّح السبب.","changelog.ce67fa868077":"<strong>نافذة اختصارات لوحة المفاتيح.</strong> اضغط ? أو زرّها في الشريط العلوي لترى كل الاختصارات.","changelog.4ca2136708d7":"<strong>مشروعك يتذكّر.</strong> حفظ مشروعك في DAW يحفظ الأغنية وتعديلاتها ومزجها وكلماتها والبيانو والعرض وأسماء المشاركين، وعند إعادة الفتح يعود كل شيء كما كان.","changelog.e60841228886":"<strong>معاينة الخط الزمني أكبر</strong>، وتعرض الكلمات التي تُغنّى في تلك اللحظة.","changelog.1dca7b1d60db":"<span class=\"release__meta\"><span class=\"release__ver\">v0.3.0</span><time class=\"release__date\" datetime=\"2026-10-14\">2026-10-14</time></span>","changelog.d35d794c003e":"الأيدي الواقعية. تعزف الآن يدان على البيانو فوق مسرح Handscore كما يفعل عازف البيانو — كل إصبع مختار للمقطع، والإبهام يمرّ من تحت اليد في السلّم الموسيقي، وترتفع يدٌ فوق الأخرى حين تتطلّب الموسيقى تقاطع اليدين. اثنتان وستون قطعة كلاسيكية من الملكية العامة جاهزة للتعلّم، من Mary Had a Little Lamb إلى Silent Night وThe Star-Spangled Banner، ويتيح لك شريط التشغيل أسفل المسرح الإيقاف المؤقت والترجيع والتقديم السريع أو السحب إلى أي لحظة، وأنت تسمع النغمات في أثناء ذلك.","changelog.0390e4a43a0a":"<strong>أيدٍ واقعية على لوحة المفاتيح.</strong> يدان تنتهيان عند الرسغ تعزفان كل نغمة على البيانوهات الأربعة جميعها: كل إصبع مختار كما يختاره عازف البيانو، والإبهام يمرّ من تحت اليد في السلالم الموسيقية، والأكوردات الواسعة تُطال، والإبهام مستلقٍ على جانبه ومنحنٍ برفق، وترتفع يدٌ فوق الأخرى لتتقاطعا. وحين لا يُعزف شيء، تستريحان على المفاتيح متأهبتين.","changelog.2c009dbabcfe":"<strong>توزيع الأصابع محسوم قبل أن تصدر أي نغمة.</strong> يقرّر Handscore أي يد تعزف كل نغمة وبأي إصبع قبل أن تُعزف الموسيقى، فتصل اليدان لحظة انخفاض المفاتيح لا بعدها.","changelog.216f61cb53a3":"<strong>اختر الوضع.</strong> صار الزر أعلى اليمين (أو P) يحمل عبارة <em>اختر الوضع</em>، ويفتح خياراتك حسب الفئة: الآلات، والكلاسيكيات، ومقاطع، والدروس (تصل في إصدار لاحق).","changelog.44952a5f65fd":"<strong>اثنتان وستون قطعة كلاسيكية للتعلّم.</strong> أغاني أطفال، وأغاني عيد الميلاد وتراتيله، وأغانٍ شعبية، وترانيم روحية وأناشيد، وألحان كلاسيكية، ومقطوعات بيانو محبوبة — Chopsticks وJingle Bells وSilent Night و«نشيد الفرح» وFür Elise وThe Entertainer وThe Star-Spangled Banner وغيرها — كلٌّ منها موزّعة لليدين، اللحن في اليمنى والأكوردات في اليسرى. ابحث عنها بالعنوان أو المؤلف. وجميعها من الملكية العامة.","changelog.d8fc29c977d3":"<strong>مقاطع للمشاهدة.</strong> سلّم موسيقي، وii–V–I، وأربيجيو، وتقاطع لليدين، كلٌّ منها نظرة سريعة على اليدين وهما تعملان.","changelog.d0ff9a5e5f3f":"<strong>شريط التشغيل.</strong> التشغيل والإيقاف المؤقت والإيقاف والترجيع والتقديم السريع أسفل المسرح، مع خط زمني يعرض زمن الأغنية ومازوراتها. مرّر المؤشر فوق الخط الزمني لترى اليدين في تلك اللحظة في معاينة صغيرة. اسحب على امتداده، أو اضغط مطوّلًا على الترجيع أو التقديم السريع، فتسمع كل نغمة تمرّ بها، في كلا الاتجاهين.","changelog.197a823169eb":"<strong>مترونوم.</strong> شغّله فتحدّد نقرةٌ كل نبضة، والأولى من كل مازورة أعلى، بينما تُظهر النقاط بجانب حرف <em>M</em> النبضة.","changelog.f94e5b4b235f":"<strong>مفتاح المسافة يشغّل ويوقف مؤقتًا.</strong>","changelog.dd397e7c80b2":"<strong>صار زر الآلة الآن «اختر الوضع»</strong>، ويُعلَّم البيانو الذي تختاره بين الآلات بعبارة <em>الحالية</em>.","changelog.c59c86e0cd28":"<span class=\"release__meta\"><span class=\"release__ver\">v0.2.0</span><time class=\"release__date\" datetime=\"2026-10-14\">2026-10-14</time></span>","changelog.14c84d5c455f":"البيانوهات الحقيقية. تقف الآن أربعة بيانوهات على مسرح Handscore — بيانو كبير للحفلات، وبيانو كبير للصالون، وبيانو قائم للاستوديو، وبيانو قائم قديم من حانات الغرب — كلٌّ منها مُضاء كما في الاستوديو، ولكلٍّ منها صوته الخاص. انقر على مفتاح أو اعزف من DAW لديك فيعزف البيانو: ينخفض المفتاح، ويخفت اسمه، وتُبقي دواسة الاستدامة ما تتركه من نغمات. ويتيح لك منتقي البيانو أن تسمع البيانو قبل أن تختاره.","changelog.a8f76e859570":"<strong>أربعة بيانوهات حقيقية.</strong> Grand Piano وAcoustic Piano وUpright Piano وHonky-Tonk Piano، لكلٍّ منها شكله وطلاؤه وصوته، في كلتا السمتين.","changelog.6f544a8bd67f":"<strong>اعزف على المفاتيح.</strong> انقر على مفتاح لتسمعه، أو مرّر المؤشر فوق المفاتيح لتعزفها واحدًا تلو الآخر. يعزف MIDI القادم من DAW لديك على البيانو ويحرّك مفاتيحه، وتُبقي دواسة الاستدامة النغمات التي تتركها حتى ترفع قدمك عنها.","changelog.3f265130a08f":"<strong>مفاتيح تتحرك كمفاتيح البيانو.</strong> ينخفض كل مفتاح دائرًا على نقطة ارتكازه، وكلما عُزف بقوة أكبر كان أسرع، ويخفت اسمه ما دام منخفضًا ثم يعود حين يرتفع.","changelog.7fd2c1ed940d":"<strong>منتقي البيانو.</strong> يفتح زر الآلة أعلى اليمين (أو P) أربع بطاقات. يعزف زر <em>معاينة</em> جملة قصيرة على ذلك البيانو دون التبديل إليه؛ ويضعه زر <em>اختيار</em> على المسرح بانتقال تدريجي من البيانو السابق. يُحفظ اختيارك مع مشروعك.","changelog.72aa386a33ff":"<strong>جودة تناسب جهازك.</strong> يقيس Handscore مدى سرعة جهازك في رسم المسرح، ويستقر على الجودة التي يستطيع الحفاظ عليها بسلاسة.","changelog.1246fc93bca0":"الإصلاحات","changelog.58e041aeca75":"<strong>المفاتيح تواكب حتى على جهاز مشغول.</strong> المفتاح الذي كان يُعزف بينما يتباطأ الجهاز في الرسم قد يبقى مرفوعًا، أو يبقى اسمه خافتًا إلى النصف؛ أما الآن فينتهي دائمًا حيث تركه عزفك.","changelog.e6eef73c000a":"<span class=\"release__meta\"><span class=\"release__ver\">v0.1.0</span><time class=\"release__date\" datetime=\"2026-10-12\">2026-10-12</time></span>","changelog.ff94e0b1d59f":"الأساس. يُحمَّل Freally Handscore كمكوّن إضافي بصيغتي CLAP وVST3 وكتطبيق مستقل، ويطلب منك قبول ترخيصه، ويُفتح على مسرحه: لوحة مفاتيح من 88 مفتاحًا بمقاسات بيانو حقيقي، اسم كل مفتاح مكتوب على واجهته. لا يُولَّد شيء بعد — فذلك يصل مع البيانوهات الحقيقية والأيدي.","changelog.37cee751dc57":"<strong>المكوّن الإضافي والتطبيق المستقل.</strong> CLAP وVST3 على Windows (ويُبنى AU على جهاز Mac)، وتطبيق مستقل يحمل أيقونة Handscore في شريط عنوانه وفي شريط المهام.","changelog.bf0d03d43bfd":"<strong>اتفاقية الترخيص أولًا.</strong> حتى توافق، لا يفعل Handscore شيئًا. تُحفظ إجابتك على جهازك وتشترك فيها كل نسخة مفتوحة، في كل DAW وفي التطبيق المستقل.","changelog.28bc52fb055e":"<strong>المسرح.</strong> لوحة مفاتيح من 88 مفتاحًا، من A0 إلى C8، بمقاسات بيانو حقيقي، تملأ عرض النافذة. اسم كل مفتاح مكتوب على واجهته — على المفاتيح البيضاء بحبر داكن، وعلى السوداء بالأبيض — ويختفي ما دام المفتاح مضغوطًا.","changelog.d51fdbedfc0e":"<strong>الوضعان الفاتح والداكن.</strong> المفتاح أعلى اليسار؛ ويتذكّر Handscore اختيارك.","changelog.9e0609310c1a":"<strong>ثماني عشرة لغة.</strong> يبدأ Handscore بلغة نظامك.","changelog.f1cf7c9dfaa8":"<strong>عرض ثلاثي الأبعاد يقول متى لا يستطيع الرسم.</strong> النافذة التي تفتقر إلى WebGL 2 تشرح كيفية تفعيله بدلًا من ألا تعرض شيئًا.","changelog.0fe089d138d3":"<strong>الأعطال تُحفظ ولا تُرسَل أبدًا.</strong> إذا توقّف Handscore يومًا على نحو غير متوقع، يُحفظ تقرير قصير على جهازك للتشغيل التالي. لا يغادر شيء جهازك ما لم تختر الإبلاغ عنه."};
